-- =====================================================================
-- MealBridge setup.sql : ONE file that builds the whole database.
-- Generated by tools/rebuild.sh from sql/01,03-08 (do not edit here;
-- edit the numbered files and re-run). Run as a MySQL admin:
--     mysql -u root -p < sql/setup.sql
-- Drops and recreates the 'mealbridge' database and the 4 demo logins.
-- Contains SYNTHETIC data only.
-- =====================================================================

-- >>>>>>>>>>>>>>>>>>>> sql/01_schema.sql <<<<<<<<<<<<<<<<<<<<

-- =====================================================================
-- MealBridge : relational schema (DDL)                 Stage 3 deliverable
-- Target: MySQL 8.0.16+ (needs CHECK constraints, SRID-aware spatial
--         indexes, generated columns, window functions later on).
--
-- Reading guide for the viva:
--   * Every table states its primary key, candidate keys (UNIQUE) and
--     foreign keys explicitly. Business rules that fit in a single row
--     are CHECK constraints; rules that span tables (e.g. "a mess admin
--     must belong to a MESS site") are enforced by triggers in Stage 4.
--   * Comments marked [FD] list the functional dependencies used in the
--     normalization write-up (03_database_design.md, section 5).
--   * Comments marked [IDX] point to the indexing strategy (section 6).
--   * Two columns are deliberate, trigger-maintained denormalizations:
--       surplus_batch.safe_until  and  shelter_day.reserved_kg
--     Both are justified in section 5.4 of the design document.
-- =====================================================================

-- Force the connection character set, whatever the client defaults to.
-- The Windows mysql client connects as cp850 (the console code page).
-- Procedures, functions and triggers remember the connection character set
-- they were created under, so under cp850 their string literals become
-- cp850 and comparing them with utf8mb4 columns fails with
-- "Illegal mix of collations". SET NAMES makes setup.sql safe to load
-- from any client, with or without --default-character-set=utf8mb4.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;

DROP DATABASE IF EXISTS mealbridge;
CREATE DATABASE mealbridge
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;
USE mealbridge;

-- ---------------------------------------------------------------------
-- 1. CAMPUS : a university campus that runs one or more messes.
-- [FD] campus_id -> name, city ;  name -> campus_id (candidate key)
-- ---------------------------------------------------------------------
CREATE TABLE campus (
  campus_id   SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(120) NOT NULL,
  city        VARCHAR(80)  NOT NULL,
  CONSTRAINT uq_campus_name UNIQUE (name)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 2. SITE : EER superclass of every physical location food moves between.
--    Specialization {MESS, SHELTER} is DISJOINT and TOTAL: each site is
--    exactly one of the two, recorded by the discriminator site_type.
--    location is a geographic POINT (SRID 4326 = WGS-84 lat/long) so we
--    can use ST_Distance_Sphere() and a SPATIAL index for "nearby" search.
-- [FD] site_id -> site_type, name, address_line, city, pincode,
--                 location, contact_phone, is_active, created_at
-- ---------------------------------------------------------------------
CREATE TABLE site (
  site_id        INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  site_type      ENUM('MESS','SHELTER') NOT NULL,
  name           VARCHAR(150) NOT NULL,
  address_line   VARCHAR(255) NOT NULL,
  city           VARCHAR(80)  NOT NULL,
  pincode        CHAR(6)      NOT NULL,
  location       POINT        NOT NULL SRID 4326,
  contact_phone  VARCHAR(15)  NOT NULL,
  is_active      BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_site_pincode CHECK (pincode REGEXP '^[1-9][0-9]{5}$'),
  CONSTRAINT chk_site_phone   CHECK (contact_phone REGEXP '^\\+?[0-9]{10,14}$'),
  -- Composite candidate key used as the target of the subtype FKs below,
  -- so a MESS row can only ever point at a site whose type is 'MESS'.
  CONSTRAINT uq_site_id_type UNIQUE (site_id, site_type),
  SPATIAL INDEX sx_site_location (location)                     -- [IDX-1]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 3. MESS : subclass of SITE (hostel / institutional kitchen = donor).
--    site_type is pinned to 'MESS' by a generated column + composite FK.
--    This makes the disjointness of the specialization a DB guarantee.
-- [FD] site_id -> campus_id, hostel_block, mess_type,
--                 daily_capacity_meals, fssai_license_no
--      fssai_license_no -> site_id  (candidate key)
-- ---------------------------------------------------------------------
CREATE TABLE mess (
  site_id               INT UNSIGNED PRIMARY KEY,
  site_type             ENUM('MESS','SHELTER')
                          GENERATED ALWAYS AS ('MESS') STORED,
  campus_id             SMALLINT UNSIGNED NOT NULL,
  hostel_block          VARCHAR(40)  NOT NULL,
  mess_type             ENUM('VEG','NON_VEG','MIXED','SPECIAL') NOT NULL,
  daily_capacity_meals  INT UNSIGNED NOT NULL,
  fssai_license_no      CHAR(14)     NOT NULL,   -- FSSAI licence numbers are 14 digits
  CONSTRAINT uq_mess_fssai UNIQUE (fssai_license_no),
  CONSTRAINT chk_mess_capacity CHECK (daily_capacity_meals > 0),
  CONSTRAINT chk_mess_fssai CHECK (fssai_license_no REGEXP '^[0-9]{14}$'),
  CONSTRAINT fk_mess_site FOREIGN KEY (site_id, site_type)
    REFERENCES site (site_id, site_type),
  CONSTRAINT fk_mess_campus FOREIGN KEY (campus_id)
    REFERENCES campus (campus_id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 4. SHELTER : subclass of SITE (recipient organisation).
-- [FD] site_id -> shelter_type, registration_no, beneficiary_count,
--                 has_refrigeration, default_capacity_kg
--      registration_no -> site_id (candidate key)
-- ---------------------------------------------------------------------
CREATE TABLE shelter (
  site_id              INT UNSIGNED PRIMARY KEY,
  site_type            ENUM('MESS','SHELTER')
                         GENERATED ALWAYS AS ('SHELTER') STORED,
  shelter_type         ENUM('ORPHANAGE','OLD_AGE_HOME','HOMELESS_SHELTER',
                            'HOSPITAL_ATTENDANTS','COMMUNITY_KITCHEN',
                            'OTHER') NOT NULL,
  registration_no      VARCHAR(40)  NOT NULL,  -- NGO / Darpan / trust reg. no.
  beneficiary_count    INT UNSIGNED NOT NULL,
  has_refrigeration    BOOLEAN      NOT NULL DEFAULT FALSE,
  default_capacity_kg  DECIMAL(7,2) NOT NULL,  -- how much cooked food it can take per day
  CONSTRAINT uq_shelter_reg UNIQUE (registration_no),
  CONSTRAINT chk_shelter_benef CHECK (beneficiary_count > 0),
  CONSTRAINT chk_shelter_cap   CHECK (default_capacity_kg > 0),
  CONSTRAINT fk_shelter_site FOREIGN KEY (site_id, site_type)
    REFERENCES site (site_id, site_type)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 5. DIET_TAG : lookup of dietary characteristics (VEG, CONTAINS_EGG, ...).
--    Used twice: what a batch CONTAINS, and what a shelter EXCLUDES.
-- [FD] tag_code -> description
-- ---------------------------------------------------------------------
CREATE TABLE diet_tag (
  tag_code     VARCHAR(30) PRIMARY KEY,
  description  VARCHAR(200) NOT NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 6. SHELTER_DIET_EXCLUSION : multivalued attribute of SHELTER, moved to
--    its own table to satisfy 1NF ("no beef, no onion/garlic" etc).
-- [FD] none beyond the trivial one; the whole row is the key (BCNF).
-- ---------------------------------------------------------------------
CREATE TABLE shelter_diet_exclusion (
  shelter_site_id  INT UNSIGNED NOT NULL,
  tag_code         VARCHAR(30)  NOT NULL,
  PRIMARY KEY (shelter_site_id, tag_code),
  CONSTRAINT fk_sde_shelter FOREIGN KEY (shelter_site_id)
    REFERENCES shelter (site_id) ON DELETE CASCADE,
  CONSTRAINT fk_sde_tag FOREIGN KEY (tag_code)
    REFERENCES diet_tag (tag_code)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 7. APP_USER : every login. role drives the MySQL role it maps to
--    (Stage 5). MESS_ADMIN / SHELTER users belong to exactly one site;
--    VOLUNTEER / PLATFORM_ADMIN users belong to none (row-level CHECK).
--    "site type matches role" spans two tables -> trigger in Stage 4.
-- [FD] user_id -> full_name, email, phone, password_hash, role,
--                 site_id, is_active, created_at
--      email -> user_id (candidate key)
-- ---------------------------------------------------------------------
CREATE TABLE app_user (
  user_id        INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  full_name      VARCHAR(120) NOT NULL,
  email          VARCHAR(190) NOT NULL,
  phone          VARCHAR(15)  NOT NULL,
  password_hash  CHAR(60)     NOT NULL,          -- bcrypt output, never plain text
  role           ENUM('MESS_ADMIN','SHELTER','VOLUNTEER','PLATFORM_ADMIN') NOT NULL,
  site_id        INT UNSIGNED NULL,
  is_active      BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_user_email UNIQUE (email),
  CONSTRAINT chk_user_email CHECK (email LIKE '%_@_%._%'),
  CONSTRAINT chk_user_site_by_role CHECK (
       (role IN ('MESS_ADMIN','SHELTER')         AND site_id IS NOT NULL)
    OR (role IN ('VOLUNTEER','PLATFORM_ADMIN')   AND site_id IS NULL)),
  CONSTRAINT fk_user_site FOREIGN KEY (site_id) REFERENCES site (site_id),
  INDEX ix_user_site (site_id)                                  -- [IDX-2]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 8. VOLUNTEER : subclass of APP_USER (partial specialization: only
--    users with role VOLUNTEER have a row). Extra attributes for routing.
-- [FD] user_id -> vehicle_type, max_load_kg, home_location,
--                 is_available, verified_at
-- ---------------------------------------------------------------------
CREATE TABLE volunteer (
  user_id        INT UNSIGNED PRIMARY KEY,
  vehicle_type   ENUM('BICYCLE','TWO_WHEELER','AUTO','CAR','VAN') NOT NULL,
  max_load_kg    DECIMAL(6,2) NOT NULL,
  home_location  POINT NOT NULL SRID 4326,
  is_available   BOOLEAN NOT NULL DEFAULT TRUE,
  verified_at    DATETIME NULL,                   -- NULL = ID not yet verified
  CONSTRAINT chk_vol_load CHECK (max_load_kg > 0),
  CONSTRAINT fk_vol_user FOREIGN KEY (user_id)
    REFERENCES app_user (user_id) ON DELETE CASCADE,
  SPATIAL INDEX sx_vol_home (home_location)                     -- [IDX-3]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 9. FOOD_CATEGORY : reference data that drives the PERISHABILITY CLOCK.
--    safe_hours_* values MUST be sourced from food-safety guidance before
--    real use. Seed values in Stage 4 will be marked UNVERIFIED.
--    co2e_kg_per_kg is the emission factor for "carbon avoided"; it is
--    NULL until a cited factor is entered (no invented numbers).
-- [FD] category_id -> name, risk_level, safe_hours_ambient,
--                     safe_hours_hot_held, safe_hours_chilled,
--                     kg_per_meal, co2e_kg_per_kg, values_source
--      name -> category_id (candidate key)
-- ---------------------------------------------------------------------
CREATE TABLE food_category (
  category_id          SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name                 VARCHAR(80) NOT NULL,
  risk_level           ENUM('LOW','MEDIUM','HIGH') NOT NULL,
  safe_hours_ambient   DECIMAL(4,1) NOT NULL,
  safe_hours_hot_held  DECIMAL(4,1) NOT NULL,
  safe_hours_chilled   DECIMAL(4,1) NOT NULL,
  kg_per_meal          DECIMAL(4,3) NOT NULL,   -- converts kg to meal-equivalents
  co2e_kg_per_kg       DECIMAL(6,3) NULL,
  -- Where the numbers above came from. Seed rows say 'TO VERIFY ...' so
  -- an unsourced value can never be mistaken for a cited one (Stage 4).
  values_source        VARCHAR(255) NOT NULL DEFAULT 'TO VERIFY: no source cited',
  CONSTRAINT uq_category_name UNIQUE (name),
  CONSTRAINT chk_cat_hours CHECK (
        safe_hours_ambient  > 0
    AND safe_hours_hot_held > 0
    AND safe_hours_chilled  >= safe_hours_ambient),
  CONSTRAINT chk_cat_meal CHECK (kg_per_meal > 0)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 10. SURPLUS_BATCH : one posting of surplus cooked food by a mess.
--     safe_until = cooked_at + safe_hours(category, storage). It is a
--     SNAPSHOT taken by a BEFORE INSERT trigger (Stage 4), so later edits
--     to food_category never silently change an already-posted deadline.
--     A batch is claimed WHOLE (no partial claims) - see design doc 4.3.
-- [FD] batch_id -> mess_site_id, category_id, posted_by, meal_slot,
--                  description, quantity_kg, storage, cooked_at,
--                  packed_at, safe_until, status, created_at
-- ---------------------------------------------------------------------
CREATE TABLE surplus_batch (
  batch_id      INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  mess_site_id  INT UNSIGNED NOT NULL,
  category_id   SMALLINT UNSIGNED NOT NULL,
  posted_by     INT UNSIGNED NOT NULL,
  meal_slot     ENUM('BREAKFAST','LUNCH','SNACKS','DINNER') NOT NULL,
  description   VARCHAR(255) NOT NULL,
  quantity_kg   DECIMAL(7,2) NOT NULL,
  storage       ENUM('AMBIENT','HOT_HELD','CHILLED') NOT NULL,
  cooked_at     DATETIME NOT NULL,
  packed_at     DATETIME NULL,
  safe_until    DATETIME NOT NULL,
  status        ENUM('AVAILABLE','CLAIMED','IN_TRANSIT','DELIVERED',
                     'EXPIRED','CANCELLED') NOT NULL DEFAULT 'AVAILABLE',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_batch_qty    CHECK (quantity_kg > 0 AND quantity_kg <= 2000),
  CONSTRAINT chk_batch_order  CHECK (cooked_at <= created_at),
  CONSTRAINT chk_batch_pack   CHECK (packed_at IS NULL OR packed_at >= cooked_at),
  CONSTRAINT chk_batch_expiry CHECK (safe_until > cooked_at),
  CONSTRAINT fk_batch_mess FOREIGN KEY (mess_site_id) REFERENCES mess (site_id),
  CONSTRAINT fk_batch_cat  FOREIGN KEY (category_id)  REFERENCES food_category (category_id),
  CONSTRAINT fk_batch_user FOREIGN KEY (posted_by)    REFERENCES app_user (user_id),
  -- Live feed + auto-expire job: "status = AVAILABLE ordered by deadline"
  INDEX ix_batch_status_deadline (status, safe_until),          -- [IDX-4]
  -- Mess dashboard / history: "this mess's batches, newest first"
  INDEX ix_batch_mess_created (mess_site_id, created_at)        -- [IDX-5]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 11. BATCH_DIET_TAG : multivalued attribute of SURPLUS_BATCH (1NF).
--     Matching rule: a shelter may receive a batch only if NO tag of the
--     batch appears in that shelter's exclusion list (NOT EXISTS query).
-- ---------------------------------------------------------------------
CREATE TABLE batch_diet_tag (
  batch_id  INT UNSIGNED NOT NULL,
  tag_code  VARCHAR(30)  NOT NULL,
  PRIMARY KEY (batch_id, tag_code),
  CONSTRAINT fk_bdt_batch FOREIGN KEY (batch_id)
    REFERENCES surplus_batch (batch_id) ON DELETE CASCADE,
  CONSTRAINT fk_bdt_tag FOREIGN KEY (tag_code) REFERENCES diet_tag (tag_code),
  INDEX ix_bdt_tag (tag_code)                                   -- [IDX-6]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 12. SHELTER_DAY : per-shelter, per-day need and capacity.
--     reserved_kg is maintained by triggers on CLAIM (Stage 4) and the
--     CHECK below makes over-filling a shelter impossible at DB level.
-- [FD] (shelter_site_id, day) -> meals_needed, capacity_kg, reserved_kg
-- ---------------------------------------------------------------------
CREATE TABLE shelter_day (
  shelter_site_id  INT UNSIGNED NOT NULL,
  day              DATE NOT NULL,
  meals_needed     INT UNSIGNED NOT NULL,
  capacity_kg      DECIMAL(7,2) NOT NULL,
  reserved_kg      DECIMAL(7,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (shelter_site_id, day),
  CONSTRAINT chk_sd_cap CHECK (capacity_kg > 0),
  CONSTRAINT chk_sd_reserved CHECK (reserved_kg >= 0 AND reserved_kg <= capacity_kg),
  CONSTRAINT fk_sd_shelter FOREIGN KEY (shelter_site_id) REFERENCES shelter (site_id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 13. CLAIM : a shelter claiming a batch.
--     DOUBLE-CLAIM GUARD, layer 2 (layer 1 is SELECT ... FOR UPDATE in the
--     claim procedure): active_batch_id equals batch_id while the claim is
--     live and NULL otherwise. A UNIQUE index on it means at most ONE live
--     claim per batch, because UNIQUE ignores NULLs. This emulates a
--     partial unique index, which MySQL does not support directly.
--     match_score and distance_km are snapshots of the score at claim
--     time (for the fairness audit), not values derivable later.
-- [FD] claim_id -> batch_id, shelter_site_id, claimed_by, claimed_at,
--                  match_score, distance_km, status, closed_at,
--                  close_reason
--      (batch_id, status) -> active_batch_id   (generated column)
-- ---------------------------------------------------------------------
CREATE TABLE claim (
  claim_id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  batch_id         INT UNSIGNED NOT NULL,
  shelter_site_id  INT UNSIGNED NOT NULL,
  claimed_by       INT UNSIGNED NOT NULL,
  claimed_at       DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  match_score      DECIMAL(5,2) NOT NULL,
  distance_km      DECIMAL(6,2) NOT NULL,
  status           ENUM('ACTIVE','FULFILLED','CANCELLED','REJECTED')
                     NOT NULL DEFAULT 'ACTIVE',
  closed_at        DATETIME(3)  NULL,
  close_reason     VARCHAR(255) NULL,
  active_batch_id  INT UNSIGNED
                     GENERATED ALWAYS AS
                     (IF(status IN ('ACTIVE','FULFILLED'), batch_id, NULL)) STORED,
  CONSTRAINT uq_claim_one_live_per_batch UNIQUE (active_batch_id),
  CONSTRAINT chk_claim_score CHECK (match_score BETWEEN 0 AND 100),
  CONSTRAINT chk_claim_dist  CHECK (distance_km >= 0),
  CONSTRAINT chk_claim_close CHECK (
       (status = 'ACTIVE' AND closed_at IS NULL)
    OR (status <> 'ACTIVE' AND closed_at IS NOT NULL)),
  CONSTRAINT fk_claim_batch   FOREIGN KEY (batch_id)        REFERENCES surplus_batch (batch_id),
  CONSTRAINT fk_claim_shelter FOREIGN KEY (shelter_site_id) REFERENCES shelter (site_id),
  CONSTRAINT fk_claim_user    FOREIGN KEY (claimed_by)      REFERENCES app_user (user_id),
  -- Fairness and impact views group by shelter over a time window
  INDEX ix_claim_shelter_time (shelter_site_id, claimed_at),    -- [IDX-7]
  INDEX ix_claim_batch (batch_id)                               -- [IDX-8]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 14. PICKUP_TRIP : one volunteer run that may cover several messes and
--     several shelters (pickup batching).
-- [FD] trip_id -> volunteer_id, status, planned_start, started_at,
--                 completed_at, planned_distance_km
-- ---------------------------------------------------------------------
CREATE TABLE pickup_trip (
  trip_id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  volunteer_id         INT UNSIGNED NOT NULL,
  status               ENUM('PLANNED','IN_PROGRESS','COMPLETED','ABORTED')
                         NOT NULL DEFAULT 'PLANNED',
  planned_start        DATETIME NOT NULL,
  started_at           DATETIME NULL,
  completed_at         DATETIME NULL,
  planned_distance_km  DECIMAL(6,2) NULL,
  CONSTRAINT chk_trip_times CHECK (
        (started_at IS NULL OR started_at >= planned_start - INTERVAL 1 DAY)
    AND (completed_at IS NULL OR (started_at IS NOT NULL AND completed_at >= started_at))),
  CONSTRAINT fk_trip_vol FOREIGN KEY (volunteer_id) REFERENCES volunteer (user_id),
  INDEX ix_trip_vol_status (volunteer_id, status)               -- [IDX-9]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 15. TRIP_STOP : WEAK ENTITY owned by PICKUP_TRIP. Identified by
--     (trip_id, stop_seq): stop 1, 2, 3 ... of that trip.
-- [FD] (trip_id, stop_seq) -> site_id, stop_type, planned_eta,
--                             arrived_at, departed_at
-- ---------------------------------------------------------------------
CREATE TABLE trip_stop (
  trip_id      INT UNSIGNED NOT NULL,
  stop_seq     TINYINT UNSIGNED NOT NULL,
  site_id      INT UNSIGNED NOT NULL,
  stop_type    ENUM('PICKUP','DROP') NOT NULL,
  planned_eta  DATETIME NOT NULL,
  arrived_at   DATETIME NULL,
  departed_at  DATETIME NULL,
  PRIMARY KEY (trip_id, stop_seq),
  CONSTRAINT chk_stop_seq CHECK (stop_seq BETWEEN 1 AND 20),
  CONSTRAINT chk_stop_times CHECK (
    departed_at IS NULL OR (arrived_at IS NOT NULL AND departed_at >= arrived_at)),
  CONSTRAINT fk_stop_trip FOREIGN KEY (trip_id)
    REFERENCES pickup_trip (trip_id) ON DELETE CASCADE,
  CONSTRAINT fk_stop_site FOREIGN KEY (site_id) REFERENCES site (site_id),
  INDEX ix_stop_site (site_id)                                  -- [IDX-10]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 16. TRIP_ITEM : which claims a trip carries, and at which stops each one
--     is picked up and dropped. CHECK guarantees pickup happens before drop.
--     That the pickup stop's site is the batch's mess (and the drop stop's
--     site is the claiming shelter) spans 4 tables -> trigger in Stage 4.
-- [FD] (trip_id, claim_id) -> pickup_seq, drop_seq
-- ---------------------------------------------------------------------
CREATE TABLE trip_item (
  trip_id     INT UNSIGNED NOT NULL,
  claim_id    INT UNSIGNED NOT NULL,
  pickup_seq  TINYINT UNSIGNED NOT NULL,
  drop_seq    TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (trip_id, claim_id),
  CONSTRAINT chk_item_order CHECK (pickup_seq < drop_seq),
  CONSTRAINT fk_item_pickup FOREIGN KEY (trip_id, pickup_seq)
    REFERENCES trip_stop (trip_id, stop_seq),
  CONSTRAINT fk_item_drop FOREIGN KEY (trip_id, drop_seq)
    REFERENCES trip_stop (trip_id, stop_seq),
  CONSTRAINT fk_item_claim FOREIGN KEY (claim_id) REFERENCES claim (claim_id),
  INDEX ix_item_claim (claim_id)                                -- [IDX-11]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 17. CUSTODY_EVENT : append-only food-safety chain of custody.
--     row_hash = SHA2(prev_hash || this row's fields) is filled by a
--     trigger (Stage 4), giving a tamper-evident hash chain per batch;
--     UPDATE/DELETE are blocked by triggers and by not granting them.
-- [FD] event_id -> batch_id, claim_id, trip_id, event_type, event_time,
--                  actor_user_id, temperature_c, hygiene_ok, notes,
--                  location, prev_hash, row_hash
--      row_hash -> event_id (candidate key; SHA-256 collisions ignored)
-- ---------------------------------------------------------------------
CREATE TABLE custody_event (
  event_id       BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  batch_id       INT UNSIGNED NOT NULL,
  claim_id       INT UNSIGNED NULL,
  trip_id        INT UNSIGNED NULL,
  event_type     ENUM('COOKED','PACKED','POSTED','CLAIMED','PICKED_UP',
                      'DELIVERED','HYGIENE_CHECK','REJECTED','EXPIRED',
                      'CANCELLED') NOT NULL,
  event_time     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  actor_user_id  INT UNSIGNED NULL,            -- NULL = written by a trigger/job
  temperature_c  DECIMAL(4,1) NULL,
  hygiene_ok     BOOLEAN NULL,
  notes          VARCHAR(255) NULL,
  location       POINT SRID 4326 NULL,
  prev_hash      CHAR(64) NULL,                -- NULL only for a batch's first event
  row_hash       CHAR(64) NOT NULL,
  CONSTRAINT uq_event_hash UNIQUE (row_hash),
  CONSTRAINT chk_event_temp CHECK (temperature_c IS NULL OR temperature_c BETWEEN -30 AND 120),
  CONSTRAINT chk_event_hygiene CHECK (event_type <> 'HYGIENE_CHECK' OR hygiene_ok IS NOT NULL),
  CONSTRAINT fk_ev_batch FOREIGN KEY (batch_id)      REFERENCES surplus_batch (batch_id),
  CONSTRAINT fk_ev_claim FOREIGN KEY (claim_id)      REFERENCES claim (claim_id),
  CONSTRAINT fk_ev_trip  FOREIGN KEY (trip_id)       REFERENCES pickup_trip (trip_id),
  CONSTRAINT fk_ev_actor FOREIGN KEY (actor_user_id) REFERENCES app_user (user_id),
  -- Audit timeline: "all events of batch X in order"
  INDEX ix_ev_batch_time (batch_id, event_time)                 -- [IDX-12]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 18. MENU_ITEM : dish master used by the forecasting inputs.
-- [FD] menu_item_id -> name, category_id ; name -> menu_item_id
-- ---------------------------------------------------------------------
CREATE TABLE menu_item (
  menu_item_id  SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name          VARCHAR(100) NOT NULL,
  category_id   SMALLINT UNSIGNED NOT NULL,
  CONSTRAINT uq_menu_item_name UNIQUE (name),
  CONSTRAINT fk_mi_cat FOREIGN KEY (category_id) REFERENCES food_category (category_id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 19. MESS_MEAL_LOG : one row per mess, date and meal slot. This is the
--     history the surplus forecast is computed from (attendance vs.
--     prepared vs. left over).
-- [FD] (mess_site_id, service_date, meal_slot) -> expected_headcount,
--        actual_headcount, prepared_kg, leftover_kg
-- ---------------------------------------------------------------------
CREATE TABLE mess_meal_log (
  mess_site_id        INT UNSIGNED NOT NULL,
  service_date        DATE NOT NULL,
  meal_slot           ENUM('BREAKFAST','LUNCH','SNACKS','DINNER') NOT NULL,
  expected_headcount  INT UNSIGNED NOT NULL,
  actual_headcount    INT UNSIGNED NULL,       -- NULL until the meal is over
  prepared_kg         DECIMAL(7,2) NOT NULL,
  leftover_kg         DECIMAL(7,2) NULL,
  PRIMARY KEY (mess_site_id, service_date, meal_slot),
  CONSTRAINT chk_log_qty CHECK (
        prepared_kg > 0
    AND (leftover_kg IS NULL OR (leftover_kg >= 0 AND leftover_kg <= prepared_kg))),
  CONSTRAINT fk_log_mess FOREIGN KEY (mess_site_id) REFERENCES mess (site_id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 20. MESS_MENU : M:N between a meal service and the dishes served
--     (a meal has many dishes; a dish appears in many meals).
-- ---------------------------------------------------------------------
CREATE TABLE mess_menu (
  mess_site_id  INT UNSIGNED NOT NULL,
  service_date  DATE NOT NULL,
  meal_slot     ENUM('BREAKFAST','LUNCH','SNACKS','DINNER') NOT NULL,
  menu_item_id  SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (mess_site_id, service_date, meal_slot, menu_item_id),
  CONSTRAINT fk_menu_log FOREIGN KEY (mess_site_id, service_date, meal_slot)
    REFERENCES mess_meal_log (mess_site_id, service_date, meal_slot) ON DELETE CASCADE,
  CONSTRAINT fk_menu_item FOREIGN KEY (menu_item_id) REFERENCES menu_item (menu_item_id),
  -- "how much is left over when dish X is served" (forecast feature)
  INDEX ix_menu_item (menu_item_id)                             -- [IDX-13]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 21. SURPLUS_FORECAST : output of the SQL forecasting procedure, kept so
--     forecast accuracy can be measured later against mess_meal_log.
-- [FD] (mess_site_id, forecast_date, meal_slot, method)
--        -> predicted_kg, generated_at
-- ---------------------------------------------------------------------
CREATE TABLE surplus_forecast (
  mess_site_id   INT UNSIGNED NOT NULL,
  forecast_date  DATE NOT NULL,
  meal_slot      ENUM('BREAKFAST','LUNCH','SNACKS','DINNER') NOT NULL,
  method         VARCHAR(40) NOT NULL,          -- e.g. 'WEEKDAY_MA_4W'
  predicted_kg   DECIMAL(7,2) NOT NULL,
  generated_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (mess_site_id, forecast_date, meal_slot, method),
  CONSTRAINT chk_fc_kg CHECK (predicted_kg >= 0),
  CONSTRAINT fk_fc_mess FOREIGN KEY (mess_site_id) REFERENCES mess (site_id),
  INDEX ix_fc_date (forecast_date, meal_slot)                   -- [IDX-14]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 22. SCORING_WEIGHT : tunable weights of the fair-matching score, so the
--     platform admin can change policy without changing code.
-- [FD] weight_key -> weight_value, description
-- ---------------------------------------------------------------------
CREATE TABLE scoring_weight (
  weight_key    VARCHAR(30) PRIMARY KEY,   -- NEED, CAPACITY, DISTANCE, FAIRNESS, ...
  weight_value  DECIMAL(4,3) NOT NULL,
  description   VARCHAR(200) NOT NULL,
  CONSTRAINT chk_weight CHECK (weight_value BETWEEN 0 AND 1)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 23. NOTIFICATION : pre-alerts to shelters (forecast) and claim updates.
-- [FD] notification_id -> user_id, kind, message, batch_id, created_at, read_at
-- ---------------------------------------------------------------------
CREATE TABLE notification (
  notification_id  BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id          INT UNSIGNED NOT NULL,
  kind             ENUM('FORECAST_PREALERT','NEW_MATCH','CLAIM_UPDATE',
                        'TRIP_ASSIGNED','EXPIRY_WARNING') NOT NULL,
  message          VARCHAR(255) NOT NULL,
  batch_id         INT UNSIGNED NULL,
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  read_at          DATETIME NULL,
  CONSTRAINT fk_notif_user  FOREIGN KEY (user_id)  REFERENCES app_user (user_id) ON DELETE CASCADE,
  CONSTRAINT fk_notif_batch FOREIGN KEY (batch_id) REFERENCES surplus_batch (batch_id),
  -- "my unread notifications": read_at IS NULL filter on the user's rows
  INDEX ix_notif_user_unread (user_id, read_at, created_at)     -- [IDX-15]
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 24. AUDIT_LOG : generic row-change audit written by triggers (who
--     changed what). old/new values are JSON snapshots: they are an
--     opaque historical record, never queried relationally, which is why
--     a JSON column is acceptable here and not a 1NF violation in spirit.
-- [FD] audit_id -> table_name, row_pk, action, db_user, changed_at,
--                  old_values, new_values
-- ---------------------------------------------------------------------
CREATE TABLE audit_log (
  audit_id    BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  table_name  VARCHAR(64) NOT NULL,
  row_pk      VARCHAR(64) NOT NULL,
  action      ENUM('INSERT','UPDATE','DELETE') NOT NULL,
  db_user     VARCHAR(100) NOT NULL DEFAULT (CURRENT_USER()),
  changed_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  old_values  JSON NULL,
  new_values  JSON NULL,
  INDEX ix_audit_table_row (table_name, row_pk, changed_at)     -- [IDX-16]
) ENGINE=InnoDB;

-- >>>>>>>>>>>>>>>>>>>> sql/03_functions.sql <<<<<<<<<<<<<<<<<<<<

-- =====================================================================
-- MealBridge : stored FUNCTIONS                         Stage 4 deliverable
-- Run after 01_schema.sql.
--
-- Reading guide for the viva:
--   * A FUNCTION returns one value and can be used inside SELECT/WHERE.
--     A PROCEDURE (04_procedures.sql) is CALLed and may change data.
--   * The fair-matching score is split into one small function per
--     component, so each part can be shown and defended on its own:
--         fn_need_score, fn_capacity_score, fn_distance_score,
--         fn_perishability_score, fn_fairness_score
--     and fn_match_score combines them with the weights stored in the
--     scoring_weight table (policy is data, not code).
--   * Every function that reads tables is declared READS SQL DATA. With
--     binary logging on (MySQL 8 default) MySQL refuses to create a
--     function that does not declare its data access.
--   * Constants marked ASSUMPTION are planning values, not measured
--     facts. They must be checked in the field trial (TO VERIFY).
-- =====================================================================
USE mealbridge;
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;  -- also when run on its own; see 01_schema.sql

DROP FUNCTION IF EXISTS fn_distance_km;
DROP FUNCTION IF EXISTS fn_travel_minutes;
DROP FUNCTION IF EXISTS fn_safe_until;
DROP FUNCTION IF EXISTS fn_meals;
DROP FUNCTION IF EXISTS fn_is_diet_compatible;
DROP FUNCTION IF EXISTS fn_need_score;
DROP FUNCTION IF EXISTS fn_capacity_score;
DROP FUNCTION IF EXISTS fn_distance_score;
DROP FUNCTION IF EXISTS fn_perishability_score;
DROP FUNCTION IF EXISTS fn_fairness_score;
DROP FUNCTION IF EXISTS fn_match_score;
DROP FUNCTION IF EXISTS fn_custody_first_bad_event;

DELIMITER $$

-- ---------------------------------------------------------------------
-- fn_distance_km : great-circle distance between two SRID-4326 points.
-- ST_Distance_Sphere returns metres on a sphere of Earth's mean radius.
-- Straight-line distance UNDER-estimates road distance; the detour factor
-- in fn_travel_minutes compensates for that.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_distance_km(p_a POINT, p_b POINT)
RETURNS DECIMAL(8,3)
DETERMINISTIC NO SQL
BEGIN
  RETURN ST_Distance_Sphere(p_a, p_b) / 1000;
END$$

-- ---------------------------------------------------------------------
-- fn_travel_minutes : estimated door-to-door minutes for a volunteer.
--   ASSUMPTION (TO VERIFY): road distance = 1.4 x straight line,
--   average urban speed 20 km/h, plus 20 min handling (loading at the
--   mess, unloading at the shelter).
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_travel_minutes(p_km DECIMAL(8,3))
RETURNS DECIMAL(8,1)
DETERMINISTIC NO SQL
BEGIN
  DECLARE c_detour      DECIMAL(3,2) DEFAULT 1.40;   -- ASSUMPTION
  DECLARE c_speed_kmph  DECIMAL(5,2) DEFAULT 20.00;  -- ASSUMPTION
  DECLARE c_handling    DECIMAL(5,1) DEFAULT 20.0;   -- ASSUMPTION
  RETURN (p_km * c_detour / c_speed_kmph) * 60 + c_handling;
END$$

-- ---------------------------------------------------------------------
-- fn_safe_until : the PERISHABILITY CLOCK.
--   deadline = cooked_at + safe hours for (food category, storage mode).
--   Called once by the BEFORE INSERT trigger on surplus_batch, so the
--   deadline is a snapshot (see design doc 5.4).
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_safe_until(p_category_id SMALLINT UNSIGNED,
                              p_storage     VARCHAR(10),
                              p_cooked_at   DATETIME)
RETURNS DATETIME
READS SQL DATA
BEGIN
  DECLARE v_hours DECIMAL(4,1);
  SELECT CASE p_storage
           WHEN 'AMBIENT'  THEN safe_hours_ambient
           WHEN 'HOT_HELD' THEN safe_hours_hot_held
           WHEN 'CHILLED'  THEN safe_hours_chilled
         END
    INTO v_hours
    FROM food_category
   WHERE category_id = p_category_id;
  IF v_hours IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'fn_safe_until: unknown food category or storage mode';
  END IF;
  -- hours are DECIMAL (e.g. 2.5), so convert to minutes for DATE_ADD
  RETURN p_cooked_at + INTERVAL ROUND(v_hours * 60) MINUTE;
END$$

-- ---------------------------------------------------------------------
-- fn_meals : converts kilograms of a category into meal-equivalents.
--   "Meals saved" in every report is computed with this one function,
--   so the definition is the same everywhere.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_meals(p_kg DECIMAL(9,2), p_category_id SMALLINT UNSIGNED)
RETURNS INT
READS SQL DATA
BEGIN
  DECLARE v_kg_per_meal DECIMAL(4,3);
  SELECT kg_per_meal INTO v_kg_per_meal
    FROM food_category WHERE category_id = p_category_id;
  RETURN FLOOR(p_kg / v_kg_per_meal);
END$$

-- ---------------------------------------------------------------------
-- fn_is_diet_compatible : 1 if NO diet tag of the batch is on the
--   shelter's exclusion list, else 0. Classic NOT EXISTS (relational
--   "no element of set A is in set B").
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_is_diet_compatible(p_batch_id INT UNSIGNED,
                                      p_shelter_id INT UNSIGNED)
RETURNS TINYINT
READS SQL DATA
BEGIN
  RETURN NOT EXISTS (
    SELECT 1
      FROM batch_diet_tag         bdt
      JOIN shelter_diet_exclusion sde ON sde.tag_code = bdt.tag_code
     WHERE bdt.batch_id        = p_batch_id
       AND sde.shelter_site_id = p_shelter_id);
END$$

-- ---------------------------------------------------------------------
-- fn_need_score (0-100): share of the shelter's meals for that day that
--   are NOT yet covered by live claims. 100 = nothing covered yet.
--   If the shelter has not entered a shelter_day row, its registered
--   beneficiary_count is used as the day's need.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_need_score(p_shelter_id INT UNSIGNED, p_day DATE)
RETURNS DECIMAL(5,2)
READS SQL DATA
BEGIN
  DECLARE v_needed  INT;
  DECLARE v_covered INT;

  SELECT COALESCE(sd.meals_needed, s.beneficiary_count)
    INTO v_needed
    FROM shelter s
    LEFT JOIN shelter_day sd
           ON sd.shelter_site_id = s.site_id AND sd.day = p_day
   WHERE s.site_id = p_shelter_id;

  -- meals already promised to this shelter today (live or delivered claims)
  SELECT COALESCE(SUM(fn_meals(b.quantity_kg, b.category_id)), 0)
    INTO v_covered
    FROM claim c
    JOIN surplus_batch b ON b.batch_id = c.batch_id
   WHERE c.shelter_site_id = p_shelter_id
     AND c.status IN ('ACTIVE','FULFILLED')
     AND c.claimed_at >= p_day
     AND c.claimed_at <  p_day + INTERVAL 1 DAY;   -- sargable range, uses IDX-7

  IF v_needed IS NULL OR v_needed = 0 THEN RETURN 0; END IF;
  RETURN 100 * GREATEST(0, v_needed - v_covered) / v_needed;
END$$

-- ---------------------------------------------------------------------
-- fn_capacity_score (0-100) : "best fit".
--   remaining = capacity_kg - reserved_kg for that day.
--   NULL      = the whole batch does not fit -> shelter is NOT eligible
--               (claims are whole-batch, design decision 4.1).
--   score     = quantity / remaining. A batch that fills the remaining
--               space scores high; this keeps big-capacity shelters free
--               for big batches (like best-fit bin packing).
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_capacity_score(p_shelter_id INT UNSIGNED, p_day DATE,
                                  p_qty_kg DECIMAL(7,2))
RETURNS DECIMAL(5,2)
READS SQL DATA
BEGIN
  DECLARE v_remaining DECIMAL(8,2);
  SELECT COALESCE(sd.capacity_kg, s.default_capacity_kg) - COALESCE(sd.reserved_kg, 0)
    INTO v_remaining
    FROM shelter s
    LEFT JOIN shelter_day sd
           ON sd.shelter_site_id = s.site_id AND sd.day = p_day
   WHERE s.site_id = p_shelter_id;
  IF v_remaining IS NULL OR v_remaining < p_qty_kg THEN
    RETURN NULL;
  END IF;
  RETURN 100 * p_qty_kg / v_remaining;
END$$

-- ---------------------------------------------------------------------
-- fn_distance_score (0-100): linear decay to 0 at the service radius.
--   NULL beyond the radius. ASSUMPTION (TO VERIFY): 15 km radius.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_distance_score(p_km DECIMAL(8,3))
RETURNS DECIMAL(5,2)
DETERMINISTIC NO SQL
BEGIN
  DECLARE c_radius_km DECIMAL(5,2) DEFAULT 15.00;    -- ASSUMPTION
  IF p_km > c_radius_km THEN RETURN NULL; END IF;
  RETURN 100 * (1 - p_km / c_radius_km);
END$$

-- ---------------------------------------------------------------------
-- fn_perishability_score (0-100): how much of the food's remaining safe
--   time the trip would use up.
--   NULL = the shelter cannot be reached before the deadline (with a
--          30 min safety buffer) -> NOT eligible. This is the rule
--          "matching only considers shelters reachable before expiry".
--   score = 100 x (1 - travel / minutes_left): the closer the deadline,
--          the more a long trip is penalised.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_perishability_score(p_travel_min DECIMAL(8,1),
                                       p_minutes_left DECIMAL(10,1))
RETURNS DECIMAL(5,2)
DETERMINISTIC NO SQL
BEGIN
  DECLARE c_buffer_min DECIMAL(5,1) DEFAULT 30.0;    -- ASSUMPTION
  IF p_minutes_left IS NULL OR p_travel_min + c_buffer_min >= p_minutes_left THEN
    RETURN NULL;
  END IF;
  RETURN 100 * (1 - p_travel_min / p_minutes_left);
END$$

-- ---------------------------------------------------------------------
-- fn_fairness_score (0-100): stops one shelter from hogging donations.
--   Over the 7 days before p_as_of:
--     received_share = kg this shelter received / kg all shelters received
--     need_share     = this shelter's beneficiaries / all active shelters'
--     ratio          = received_share / need_share   (1.0 = exactly fair)
--     score          = 100 / (1 + ratio)
--   ratio 0 -> 100 (has received nothing), 1 -> 50, 3 -> 25.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_fairness_score(p_shelter_id INT UNSIGNED, p_as_of DATETIME)
RETURNS DECIMAL(5,2)
READS SQL DATA
BEGIN
  DECLARE v_mine  DECIMAL(12,2);
  DECLARE v_total DECIMAL(12,2);
  DECLARE v_benef DECIMAL(12,2);
  DECLARE v_benef_total DECIMAL(12,2);
  DECLARE v_ratio DECIMAL(12,4);

  SELECT COALESCE(SUM(IF(c.shelter_site_id = p_shelter_id, b.quantity_kg, 0)), 0),
         COALESCE(SUM(b.quantity_kg), 0)
    INTO v_mine, v_total
    FROM claim c
    JOIN surplus_batch b ON b.batch_id = c.batch_id
   WHERE c.status IN ('ACTIVE','FULFILLED')
     AND c.claimed_at >= p_as_of - INTERVAL 7 DAY
     AND c.claimed_at <  p_as_of;

  IF v_total = 0 THEN RETURN 100; END IF;   -- nobody received anything yet

  SELECT SUM(IF(s.site_id = p_shelter_id, s.beneficiary_count, 0)),
         SUM(s.beneficiary_count)
    INTO v_benef, v_benef_total
    FROM shelter s JOIN site t ON t.site_id = s.site_id
   WHERE t.is_active;

  IF v_benef = 0 THEN RETURN 0; END IF;
  SET v_ratio = (v_mine / v_total) / (v_benef / v_benef_total);
  RETURN 100 / (1 + v_ratio);
END$$

-- ---------------------------------------------------------------------
-- fn_match_score (0-100, or NULL = not eligible) for batch x shelter at
-- time p_as_of.
--   Hard filters (any one fails -> NULL):
--     shelter inactive, diet exclusion, batch does not fit remaining
--     capacity, outside service radius, cannot arrive before expiry.
--   Otherwise: weighted average of the five component scores, with the
--   weights read from scoring_weight and normalised to sum to 1.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_match_score(p_batch_id INT UNSIGNED,
                               p_shelter_id INT UNSIGNED,
                               p_as_of DATETIME)
RETURNS DECIMAL(5,2)
READS SQL DATA
BEGIN
  DECLARE v_qty DECIMAL(7,2);
  DECLARE v_safe_until DATETIME;
  DECLARE v_mess_loc POINT;
  DECLARE v_shelter_loc POINT;
  DECLARE v_active BOOLEAN;
  DECLARE v_km DECIMAL(8,3);
  DECLARE v_need, v_cap, v_dist, v_perish, v_fair DECIMAL(5,2);
  DECLARE w_need, w_cap, w_dist, w_perish, w_fair DECIMAL(4,3);
  DECLARE v_day DATE DEFAULT DATE(p_as_of);

  SELECT b.quantity_kg, b.safe_until, ms.location
    INTO v_qty, v_safe_until, v_mess_loc
    FROM surplus_batch b JOIN site ms ON ms.site_id = b.mess_site_id
   WHERE b.batch_id = p_batch_id;

  SELECT t.location, t.is_active INTO v_shelter_loc, v_active
    FROM shelter s JOIN site t ON t.site_id = s.site_id
   WHERE s.site_id = p_shelter_id;

  IF v_qty IS NULL OR v_shelter_loc IS NULL OR NOT v_active THEN RETURN NULL; END IF;
  IF NOT fn_is_diet_compatible(p_batch_id, p_shelter_id) THEN RETURN NULL; END IF;

  SET v_km     = fn_distance_km(v_mess_loc, v_shelter_loc);
  SET v_need   = fn_need_score(p_shelter_id, v_day);
  SET v_cap    = fn_capacity_score(p_shelter_id, v_day, v_qty);
  SET v_dist   = fn_distance_score(v_km);
  SET v_perish = fn_perishability_score(fn_travel_minutes(v_km),
                   TIMESTAMPDIFF(SECOND, p_as_of, v_safe_until) / 60);
  SET v_fair   = fn_fairness_score(p_shelter_id, p_as_of);

  IF v_cap IS NULL OR v_dist IS NULL OR v_perish IS NULL THEN RETURN NULL; END IF;

  -- policy weights (platform admin can change them; changes are audited)
  SELECT MAX(IF(weight_key='NEED',          weight_value, NULL)),
         MAX(IF(weight_key='CAPACITY',      weight_value, NULL)),
         MAX(IF(weight_key='DISTANCE',      weight_value, NULL)),
         MAX(IF(weight_key='PERISHABILITY', weight_value, NULL)),
         MAX(IF(weight_key='FAIRNESS',      weight_value, NULL))
    INTO w_need, w_cap, w_dist, w_perish, w_fair
    FROM scoring_weight;

  RETURN ( COALESCE(w_need,0)*v_need + COALESCE(w_cap,0)*v_cap
         + COALESCE(w_dist,0)*v_dist + COALESCE(w_perish,0)*v_perish
         + COALESCE(w_fair,0)*v_fair )
       / NULLIF(COALESCE(w_need,0)+COALESCE(w_cap,0)+COALESCE(w_dist,0)
               +COALESCE(w_perish,0)+COALESCE(w_fair,0), 0);
END$$

-- ---------------------------------------------------------------------
-- fn_custody_first_bad_event : verifies the SHA-256 hash chain of one
--   batch. Walks the batch's events in insertion order, recomputes each
--   row_hash from the previous hash + the row's fields, and returns the
--   event_id of the FIRST row that does not match (0 = chain intact).
--   The formula must stay identical to trg_custody_bi (05_triggers.sql).
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_custody_first_bad_event(p_batch_id INT UNSIGNED)
RETURNS BIGINT UNSIGNED
READS SQL DATA
BEGIN
  DECLARE v_done BOOLEAN DEFAULT FALSE;
  DECLARE v_id BIGINT UNSIGNED;
  DECLARE v_prev_stored, v_row_hash, v_expected CHAR(64);
  DECLARE v_prev_running CHAR(64) DEFAULT NULL;
  DECLARE v_payload TEXT;
  DECLARE cur CURSOR FOR
    SELECT event_id, prev_hash, row_hash,
           CONCAT_WS('|', batch_id, IFNULL(claim_id,'-'), IFNULL(trip_id,'-'),
                     event_type, DATE_FORMAT(event_time,'%Y-%m-%d %H:%i:%s.%f'),
                     IFNULL(actor_user_id,'-'), IFNULL(temperature_c,'-'),
                     IFNULL(hygiene_ok,'-'), IFNULL(notes,'-'))
      FROM custody_event
     WHERE batch_id = p_batch_id
     ORDER BY event_id;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = TRUE;

  OPEN cur;
  walk: LOOP
    FETCH cur INTO v_id, v_prev_stored, v_row_hash, v_payload;
    IF v_done THEN LEAVE walk; END IF;
    SET v_expected = SHA2(CONCAT(IFNULL(v_prev_running,'GENESIS'), '|', v_payload), 256);
    -- a row is bad if its own hash is wrong OR it does not point at the
    -- real previous row (someone deleted/reordered rows)
    IF v_row_hash <> v_expected OR NOT (v_prev_stored <=> v_prev_running) THEN
      CLOSE cur;
      RETURN v_id;
    END IF;
    SET v_prev_running = v_row_hash;
  END LOOP;
  CLOSE cur;
  RETURN 0;
END$$

DELIMITER ;

-- >>>>>>>>>>>>>>>>>>>> sql/04_procedures.sql <<<<<<<<<<<<<<<<<<<<

-- =====================================================================
-- MealBridge : STORED PROCEDURES                        Stage 4 deliverable
-- Run after 03_functions.sql, before 05_triggers.sql.
--
-- Reading guide for the viva:
--   * Every write an end user can make goes through a procedure. The
--     MySQL roles (07_roles_grants.sql) get EXECUTE on these procedures
--     but NO direct INSERT/UPDATE on the tables behind them. Procedures
--     run with SQL SECURITY DEFINER, i.e. with the privileges of their
--     creator, so they are the only door into the data ("least
--     privilege").
--   * p_user_id is the logged-in application user, passed by the API.
--     Each procedure checks that this user has the right role and site
--     (row-level ownership), because MySQL has no row-level security.
--
--   sp_register_site    platform admin adds a mess or shelter (site + subtype
--                       in one transaction = TOTAL specialization)
--   sp_post_batch       mess admin posts surplus (+ diet tags, + alerts)
--   sp_cancel_batch     mess admin withdraws an unclaimed batch
--   sp_rank_shelters    THE MATCHING PROCEDURE: ranks shelters for a
--                       batch on need, capacity, distance, perishability
--                       and fairness, and shows why others are excluded
--   sp_explain_my_eligibility  "why can't I claim this?" for the calling
--                       shelter only: each rule and factor with its numbers
--   sp_claim_batch      shelter claims a batch: TRANSACTION + FOR UPDATE
--   sp_cancel_claim     shelter backs out before pickup
--   sp_create_trip      volunteer pickup batching (multi-stop trip)
--   sp_record_pickup    volunteer confirms pickup at a mess
--   sp_record_delivery  volunteer confirms drop + hygiene check
--   sp_set_availability volunteer switches availability on/off
--   sp_expire_batches   auto-expire job (called by ev_auto_expire)
--   sp_generate_forecast surplus forecast + shelter pre-alerts
-- =====================================================================
USE mealbridge;
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;  -- also when run on its own; see 01_schema.sql

DROP PROCEDURE IF EXISTS sp_register_site;
DROP PROCEDURE IF EXISTS sp_post_batch;
DROP PROCEDURE IF EXISTS sp_cancel_batch;
DROP PROCEDURE IF EXISTS sp_rank_shelters;
DROP PROCEDURE IF EXISTS sp_claim_batch;
DROP PROCEDURE IF EXISTS sp_cancel_claim;
DROP PROCEDURE IF EXISTS sp_create_trip;
DROP PROCEDURE IF EXISTS sp_record_pickup;
DROP PROCEDURE IF EXISTS sp_record_delivery;
DROP PROCEDURE IF EXISTS sp_set_availability;
DROP PROCEDURE IF EXISTS sp_expire_batches;
DROP PROCEDURE IF EXISTS sp_generate_forecast;
DROP PROCEDURE IF EXISTS sp_explain_my_eligibility;

DELIMITER $$

-- ---------------------------------------------------------------------
-- sp_register_site : adds a MESS or a SHELTER.
--   SQL cannot force "every SITE row has exactly one subtype row" with a
--   constraint (a parent cannot require a child). So the only way the
--   application creates sites is this procedure, which inserts the SITE
--   row and its subtype row in ONE transaction: both or neither. That is
--   how the TOTAL part of the SITE specialization is guaranteed.
--   p_details (JSON) carries the subtype's own attributes, e.g.
--   shelter: {"shelter_type":"ORPHANAGE","registration_no":"R1",
--             "beneficiary_count":40,"has_refrigeration":true,
--             "default_capacity_kg":20}
--   mess:    {"campus_id":1,"hostel_block":"G","mess_type":"VEG",
--             "daily_capacity_meals":1000,"fssai_license_no":"10000000000099"}
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_register_site(
  IN  p_type     VARCHAR(10),
  IN  p_name     VARCHAR(150),
  IN  p_address  VARCHAR(255),
  IN  p_city     VARCHAR(80),
  IN  p_pincode  CHAR(6),
  IN  p_lat      DOUBLE,
  IN  p_lon      DOUBLE,
  IN  p_phone    VARCHAR(15),
  IN  p_details  JSON,
  OUT p_site_id  INT UNSIGNED)
SQL SECURITY DEFINER
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
    VALUES (p_type, p_name, p_address, p_city, p_pincode,
            ST_SRID(POINT(p_lat, p_lon), 4326), p_phone);    -- (lat, lon) for SRID 4326
    SET p_site_id = LAST_INSERT_ID();
    IF p_type = 'MESS' THEN
                        daily_capacity_meals, fssai_license_no)
      VALUES (p_site_id, p_details->>'$.campus_id', p_details->>'$.hostel_block',
              p_details->>'$.mess_type', p_details->>'$.daily_capacity_meals',
              p_details->>'$.fssai_license_no');
    ELSEIF p_type = 'SHELTER' THEN
                           has_refrigeration, default_capacity_kg)
      VALUES (p_site_id, p_details->>'$.shelter_type', p_details->>'$.registration_no',
              p_details->>'$.beneficiary_count',
              COALESCE(p_details->'$.has_refrigeration' = TRUE, FALSE),
              p_details->>'$.default_capacity_kg');
    ELSE
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'p_type must be MESS or SHELTER';
    END IF;
  COMMIT;
END$$

-- ---------------------------------------------------------------------
-- sp_post_batch : a mess admin posts a surplus batch.
--   p_diet_tags is a JSON array, e.g. '["VEG","CONTAINS_DAIRY"]'.
--   The deadline is NOT a parameter: trg_batch_bi computes it.
--   After posting, the 3 best-matching shelters get a NEW_MATCH alert.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_post_batch(
  IN  p_user_id     INT UNSIGNED,
  IN  p_category_id SMALLINT UNSIGNED,
  IN  p_meal_slot   VARCHAR(10),
  IN  p_description VARCHAR(255),
  IN  p_qty_kg      DECIMAL(7,2),
  IN  p_storage     VARCHAR(10),
  IN  p_cooked_at   DATETIME,
  IN  p_packed_at   DATETIME,
  IN  p_diet_tags   JSON,
  OUT p_batch_id    INT UNSIGNED)
SQL SECURITY DEFINER
BEGIN
  DECLARE v_mess INT UNSIGNED;
  -- any error: undo everything this call did, then re-raise to the caller
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  SELECT site_id INTO v_mess FROM app_user
   WHERE user_id = p_user_id AND role = 'MESS_ADMIN' AND is_active;
  IF v_mess IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only an active mess admin can post a batch';
  END IF;

  START TRANSACTION;
                               description, quantity_kg, storage, cooked_at,
                               packed_at, safe_until)
    VALUES (v_mess, p_category_id, p_user_id, p_meal_slot, p_description,
            p_qty_kg, p_storage, p_cooked_at, p_packed_at,
            p_cooked_at + INTERVAL 1 SECOND);   -- placeholder, overwritten by trigger
    SET p_batch_id = LAST_INSERT_ID();

    -- JSON_TABLE turns the JSON array into rows (one per tag)
    SELECT p_batch_id, jt.tag
      FROM JSON_TABLE(COALESCE(p_diet_tags, JSON_ARRAY()), '$[*]'
                      COLUMNS (tag VARCHAR(30) PATH '$')) AS jt;

    -- alert staff of the top-3 eligible shelters
    SELECT u.user_id, 'NEW_MATCH',
           CONCAT('New batch #', p_batch_id, ': ', p_qty_kg, ' kg, match score ', r.score),
           p_batch_id
      FROM (SELECT s.site_id, fn_match_score(p_batch_id, s.site_id, NOW()) AS score
              FROM shelter s) r
      JOIN app_user u ON u.site_id = r.site_id AND u.role = 'SHELTER' AND u.is_active
     WHERE r.score IS NOT NULL
     ORDER BY r.score DESC
     LIMIT 3;
  COMMIT;
END$$

-- ---------------------------------------------------------------------
-- sp_cancel_batch : withdraw an AVAILABLE batch (e.g. mess found a use).
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_cancel_batch(IN p_user_id INT UNSIGNED,
                                 IN p_batch_id INT UNSIGNED)
SQL SECURITY DEFINER
BEGIN
  DECLARE v_rows INT;
  UPDATE surplus_batch b
    JOIN app_user u ON u.user_id = p_user_id AND u.role = 'MESS_ADMIN'
                   AND u.site_id = b.mess_site_id
     SET b.status = 'CANCELLED'
   WHERE b.batch_id = p_batch_id AND b.status = 'AVAILABLE';
  SET v_rows = ROW_COUNT();
  IF v_rows = 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Not cancelled: batch is not yours or is no longer AVAILABLE';
  END IF;
END$$

-- ---------------------------------------------------------------------
-- sp_rank_shelters : THE MATCHING PROCEDURE.
--   For one batch, returns every shelter with
--     distance, travel estimate, minutes of safe time left,
--     the five component scores, the weighted match score,
--     and, if it is excluded, the reason.
--   Eligible shelters come first, best score first.
--   p_as_of = NULL means "now" (it exists so past decisions can be
--   replayed for the fairness audit).
--
--   Spatial pre-filter: a bounding box around the mess lets the R-tree
--   index on site.location (IDX-1) discard far-away shelters before any
--   exact distance is computed. 1 degree of latitude ~ 111 km.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_rank_shelters(IN p_batch_id INT UNSIGNED, IN p_as_of DATETIME)
SQL SECURITY DEFINER
BEGIN
  DECLARE v_as_of DATETIME DEFAULT COALESCE(p_as_of, NOW());
  DECLARE v_lat, v_lon, v_dlat, v_dlon DOUBLE;
  DECLARE v_box GEOMETRY;
  DECLARE c_radius_km DOUBLE DEFAULT 15;     -- same ASSUMPTION as fn_distance_score

  SELECT ST_Latitude(t.location), ST_Longitude(t.location)
    INTO v_lat, v_lon
    FROM surplus_batch b JOIN site t ON t.site_id = b.mess_site_id
   WHERE b.batch_id = p_batch_id;
  IF v_lat IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unknown batch';
  END IF;

  SET v_dlat = c_radius_km / 111.0;
  SET v_dlon = c_radius_km / (111.0 * COS(RADIANS(v_lat)));
  -- SRID 4326 axis order in MySQL is (latitude longitude)
  SET v_box = ST_GeomFromText(CONCAT('POLYGON((',
        v_lat - v_dlat, ' ', v_lon - v_dlon, ',', v_lat - v_dlat, ' ', v_lon + v_dlon, ',',
        v_lat + v_dlat, ' ', v_lon + v_dlon, ',', v_lat + v_dlat, ' ', v_lon - v_dlon, ',',
        v_lat - v_dlat, ' ', v_lon - v_dlon, '))'), 4326);

  SELECT x.shelter_id, x.shelter, x.km, x.travel_min, x.min_left,
         x.need, x.capacity, x.distance, x.perish, x.fairness,
         fn_match_score(p_batch_id, x.shelter_id, v_as_of) AS match_score,
         CASE
           WHEN NOT x.diet_ok             THEN 'EXCLUDED: diet exclusion'
           WHEN x.capacity IS NULL        THEN 'EXCLUDED: not enough capacity left today'
           WHEN x.distance IS NULL        THEN 'EXCLUDED: outside service radius'
           WHEN x.perish   IS NULL        THEN 'EXCLUDED: cannot arrive before safe-until'
           ELSE 'ELIGIBLE'
         END AS verdict
    FROM (
      SELECT s.site_id AS shelter_id, t.name AS shelter,
             ROUND(fn_distance_km(ms.location, t.location), 2)            AS km,
             ROUND(fn_travel_minutes(fn_distance_km(ms.location, t.location)))  AS travel_min,
             TIMESTAMPDIFF(MINUTE, v_as_of, b.safe_until)                 AS min_left,
             fn_is_diet_compatible(b.batch_id, s.site_id)                 AS diet_ok,
             ROUND(fn_need_score(s.site_id, DATE(v_as_of)), 1)            AS need,
             ROUND(fn_capacity_score(s.site_id, DATE(v_as_of), b.quantity_kg), 1) AS capacity,
             ROUND(fn_distance_score(fn_distance_km(ms.location, t.location)), 1) AS distance,
             ROUND(fn_perishability_score(
                     fn_travel_minutes(fn_distance_km(ms.location, t.location)),
                     TIMESTAMPDIFF(SECOND, v_as_of, b.safe_until) / 60), 1) AS perish,
             ROUND(fn_fairness_score(s.site_id, v_as_of), 1)              AS fairness
        FROM surplus_batch b
        JOIN site ms ON ms.site_id = b.mess_site_id
        JOIN shelter s
        JOIN site t  ON t.site_id = s.site_id
       WHERE b.batch_id = p_batch_id
         AND t.is_active
         AND MBRContains(v_box, t.location)          -- uses SPATIAL index IDX-1
    ) x
   ORDER BY (match_score IS NULL), match_score DESC, x.km;
END$$

-- ---------------------------------------------------------------------
-- sp_claim_batch : CONCURRENCY-SAFE CLAIM (double-claim guard, layer 1)
--
--  1. START TRANSACTION.
--  2. SELECT ... FOR UPDATE on the batch row: takes an exclusive row lock.
--     A second session running the same statement on the same batch
--     BLOCKS here until the first one commits or rolls back.
--  3. When it unblocks, a locking read always returns the LATEST
--     COMMITTED row (not the transaction's old snapshot), so the second
--     session sees status = 'CLAIMED' and is rejected cleanly.
--  4. Score is computed and snapshotted into the claim row; the claim
--     triggers then update capacity, batch status and custody.
--  5. COMMIT releases the lock.
--  Layer 2 is the UNIQUE index on claim.active_batch_id, which stops a
--  second live claim even if some code skipped this procedure.
--
--  @demo_hold_seconds (session variable, default 0) makes the procedure
--  sleep WHILE HOLDING THE LOCK, only so the race demo is visible to a
--  human. The API never sets it.
--
--  Result: p_result = 'CLAIMED' or 'REJECTED: <reason>' (never an
--  unhandled error, so the API can show a friendly message).
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_claim_batch(
  IN  p_user_id  INT UNSIGNED,
  IN  p_batch_id INT UNSIGNED,
  OUT p_claim_id INT UNSIGNED,
  OUT p_result   VARCHAR(255))
SQL SECURITY DEFINER
proc: BEGIN
  DECLARE v_shelter    INT UNSIGNED;
  DECLARE v_status     VARCHAR(12);
  DECLARE v_safe_until DATETIME;
  DECLARE v_score      DECIMAL(5,2);
  DECLARE v_km         DECIMAL(8,3);
  DECLARE v_msg        VARCHAR(255);

  -- Any SQL error (CHECK on capacity, UNIQUE on active_batch_id, a lock
  -- wait timeout, a deadlock...) -> roll back and report it.
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 v_msg = MESSAGE_TEXT;
    ROLLBACK;
    SET p_claim_id = NULL, p_result = CONCAT('REJECTED: ', v_msg);
  END;

  SET p_claim_id = NULL;

  -- who is claiming? (row-level ownership: the user's own shelter)
  SELECT site_id INTO v_shelter FROM app_user
   WHERE user_id = p_user_id AND role = 'SHELTER' AND is_active;
  IF v_shelter IS NULL THEN
    SET p_result = 'REJECTED: only active shelter staff can claim';
    LEAVE proc;
  END IF;

  START TRANSACTION;

    -- (2) the row lock
    SELECT status, safe_until INTO v_status, v_safe_until
      FROM surplus_batch
     WHERE batch_id = p_batch_id
       FOR UPDATE;

    DO SLEEP(COALESCE(@demo_hold_seconds, 0));   -- demo only, see header

    -- (3) re-check under the lock
    IF v_status IS NULL THEN
      ROLLBACK; SET p_result = 'REJECTED: no such batch'; LEAVE proc;
    END IF;
    IF v_status <> 'AVAILABLE' THEN
      ROLLBACK;
      SET p_result = CONCAT('REJECTED: batch already ', v_status, ' by another shelter');
      LEAVE proc;
    END IF;
    IF v_safe_until <= NOW() THEN
      ROLLBACK; SET p_result = 'REJECTED: batch has expired'; LEAVE proc;
    END IF;

    -- (4) eligibility + score snapshot
    SET v_score = fn_match_score(p_batch_id, v_shelter, NOW());
    IF v_score IS NULL THEN
      ROLLBACK;
      SET p_result = 'REJECTED: not eligible (diet, capacity, distance or time)';
      LEAVE proc;
    END IF;
    SELECT fn_distance_km(ms.location, ss.location) INTO v_km
      FROM surplus_batch b
      JOIN site ms ON ms.site_id = b.mess_site_id
      JOIN site ss ON ss.site_id = v_shelter
     WHERE b.batch_id = p_batch_id;

    VALUES (p_batch_id, v_shelter, p_user_id, v_score, v_km);
    SET p_claim_id = LAST_INSERT_ID();

  COMMIT;                                         -- (5) releases the lock
  SET p_result = 'CLAIMED';
END$$

-- ---------------------------------------------------------------------
-- sp_cancel_claim : shelter backs out before pickup. The claim AU
-- trigger releases capacity and re-offers the batch if still safe.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_cancel_claim(IN p_user_id INT UNSIGNED,
                                 IN p_claim_id INT UNSIGNED,
                                 IN p_reason VARCHAR(255))
SQL SECURITY DEFINER
BEGIN
  UPDATE claim c
    JOIN app_user u ON u.user_id = p_user_id AND u.role = 'SHELTER'
                   AND u.site_id = c.shelter_site_id
     SET c.status = 'CANCELLED', c.close_reason = p_reason
   WHERE c.claim_id = p_claim_id AND c.status = 'ACTIVE';
  IF ROW_COUNT() = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not cancelled: claim is not yours or not ACTIVE';
  END IF;
END$$

-- ---------------------------------------------------------------------
-- sp_create_trip : VOLUNTEER PICKUP BATCHING.
--   One trip for several claims (several messes -> several shelters).
--   Stop order is a simple, explainable heuristic, not an optimal route:
--     1. all pickups first, nearest mess to the volunteer's home first;
--     2. then all drops, nearest shelter to the last pickup first.
--   Pickups-before-drops guarantees chk_item_order (pickup_seq < drop_seq).
--   planned_eta is a running total of leg travel times, computed with
--   LAG() and SUM() OVER () window functions. A route on which any batch
--   would arrive after its safe-until time is refused.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_create_trip(
  IN  p_user_id       INT UNSIGNED,
  IN  p_claim_ids     JSON,
  IN  p_planned_start DATETIME,
  OUT p_trip_id       INT UNSIGNED)
SQL SECURITY DEFINER
BEGIN
  DECLARE v_home POINT;
  DECLARE v_max_load, v_load DECIMAL(9,2);
  DECLARE v_n_claims, v_n_ok INT;
  DECLARE v_last_pickup POINT;
  DECLARE v_n_pickups INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    DROP TEMPORARY TABLE IF EXISTS tmp_trip_claims, tmp_trip_stops;
    RESIGNAL;
  END;

  SELECT v.home_location, v.max_load_kg INTO v_home, v_max_load
    FROM volunteer v JOIN app_user u ON u.user_id = v.user_id
   WHERE v.user_id = p_user_id AND u.is_active AND v.is_available
     AND v.verified_at IS NOT NULL;
  IF v_home IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Only an available, ID-verified volunteer can take a trip';
  END IF;

  DROP TEMPORARY TABLE IF EXISTS tmp_trip_claims, tmp_trip_stops;
  CREATE TEMPORARY TABLE tmp_trip_claims (
    claim_id INT UNSIGNED PRIMARY KEY,
    mess_id INT UNSIGNED, shelter_id INT UNSIGNED, qty DECIMAL(7,2));

  SELECT c.claim_id, b.mess_site_id, c.shelter_site_id, b.quantity_kg
    FROM JSON_TABLE(p_claim_ids, '$[*]' COLUMNS (id INT UNSIGNED PATH '$')) j
    JOIN claim c         ON c.claim_id = j.id AND c.status = 'ACTIVE'
    JOIN surplus_batch b ON b.batch_id = c.batch_id AND b.status = 'CLAIMED'
                        AND b.safe_until > p_planned_start      -- food still safe at start
   WHERE NOT EXISTS (SELECT 1 FROM trip_item ti
                       JOIN pickup_trip pt ON pt.trip_id = ti.trip_id
                      WHERE ti.claim_id = c.claim_id
                        AND pt.status IN ('PLANNED','IN_PROGRESS'));

  SELECT JSON_LENGTH(p_claim_ids), COUNT(*), COALESCE(SUM(qty), 0)
    INTO v_n_claims, v_n_ok, v_load FROM tmp_trip_claims;
  IF v_n_ok = 0 OR v_n_ok <> v_n_claims THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Every claim must be ACTIVE, still safe, waiting for pickup and not on another trip';
  END IF;
  IF v_load > v_max_load THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Total load exceeds the volunteer''s max_load_kg';
  END IF;

  -- pickups ordered from home; remember where the last pickup is
  CREATE TEMPORARY TABLE tmp_trip_stops (
    seq TINYINT UNSIGNED PRIMARY KEY, site_id INT UNSIGNED, stop_type VARCHAR(6));
  SELECT ROW_NUMBER() OVER (ORDER BY fn_distance_km(v_home, t.location)),
         t.site_id, 'PICKUP'
    FROM (SELECT DISTINCT mess_id FROM tmp_trip_claims) m
    JOIN site t ON t.site_id = m.mess_id;

  SELECT t.location INTO v_last_pickup
    FROM tmp_trip_stops s JOIN site t ON t.site_id = s.site_id
   ORDER BY s.seq DESC LIMIT 1;
  -- (a MySQL TEMPORARY table cannot be opened twice in one statement,
  --  so the number of pickups is read into a variable first)
  SELECT COUNT(*) INTO v_n_pickups FROM tmp_trip_stops;

  SELECT v_n_pickups
           + ROW_NUMBER() OVER (ORDER BY fn_distance_km(v_last_pickup, t.location)),
         t.site_id, 'DROP'
    FROM (SELECT DISTINCT shelter_id FROM tmp_trip_claims) sh
    JOIN site t ON t.site_id = sh.shelter_id;

  START TRANSACTION;
    VALUES (p_user_id, 'PLANNED', p_planned_start);
    SET p_trip_id = LAST_INSERT_ID();

    -- ETA per stop = start + running sum of leg travel times
    SELECT p_trip_id, seq, site_id, stop_type,
           p_planned_start + INTERVAL ROUND(SUM(leg_min) OVER (ORDER BY seq)) MINUTE
      FROM (SELECT s.seq, s.site_id, s.stop_type,
                   fn_travel_minutes(fn_distance_km(
                       COALESCE(LAG(t.location) OVER (ORDER BY s.seq), v_home),
                       t.location)) AS leg_min
              FROM tmp_trip_stops s JOIN site t ON t.site_id = s.site_id) legs;

    UPDATE pickup_trip pt
       SET planned_distance_km = (
             SELECT ROUND(SUM(fn_distance_km(COALESCE(prev_loc, v_home), loc)), 2)
               FROM (SELECT t.location AS loc,
                            LAG(t.location) OVER (ORDER BY s.seq) AS prev_loc
                       FROM tmp_trip_stops s JOIN site t ON t.site_id = s.site_id) d)
     WHERE pt.trip_id = p_trip_id;

    -- PERISHABILITY CHECK for the whole route: every batch must reach its
    -- shelter before its safe-until time, otherwise the trip is refused
    -- (the volunteer app then plans smaller trips).
    IF EXISTS (SELECT 1
                 FROM tmp_trip_claims c
                 JOIN trip_stop sd     ON sd.trip_id = p_trip_id AND sd.site_id = c.shelter_id
                                      AND sd.stop_type = 'DROP'
                 JOIN claim cl         ON cl.claim_id = c.claim_id
                 JOIN surplus_batch b  ON b.batch_id = cl.batch_id
                WHERE sd.planned_eta >= b.safe_until) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Route too long: a batch would arrive after its safe-until time';
    END IF;

    -- joins the real trip_stop table twice (pickup side and drop side)
    SELECT p_trip_id, c.claim_id, sp.stop_seq, sd.stop_seq
      FROM tmp_trip_claims c
      JOIN trip_stop sp ON sp.trip_id = p_trip_id AND sp.site_id = c.mess_id    AND sp.stop_type = 'PICKUP'
      JOIN trip_stop sd ON sd.trip_id = p_trip_id AND sd.site_id = c.shelter_id AND sd.stop_type = 'DROP';

    VALUES (p_user_id, 'TRIP_ASSIGNED',
            CONCAT('Trip #', p_trip_id, ': ', v_n_ok, ' claim(s), ', v_load, ' kg'));
  COMMIT;

  DROP TEMPORARY TABLE IF EXISTS tmp_trip_claims, tmp_trip_stops;
END$$

-- ---------------------------------------------------------------------
-- sp_record_pickup : volunteer is at a PICKUP stop and loads the food.
--   Writes PICKED_UP custody events (with food temperature) and moves
--   every batch picked up here to IN_TRANSIT.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_record_pickup(IN p_user_id INT UNSIGNED,
                                  IN p_trip_id INT UNSIGNED,
                                  IN p_stop_seq TINYINT UNSIGNED,
                                  IN p_temperature_c DECIMAL(4,1))
SQL SECURITY DEFINER
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF NOT EXISTS (SELECT 1 FROM pickup_trip pt JOIN trip_stop ts ON ts.trip_id = pt.trip_id
                  WHERE pt.trip_id = p_trip_id AND pt.volunteer_id = p_user_id
                    AND pt.status IN ('PLANNED','IN_PROGRESS')
                    AND ts.stop_seq = p_stop_seq AND ts.stop_type = 'PICKUP'
                    AND ts.departed_at IS NULL) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not your open pickup stop';
  END IF;

  START TRANSACTION;
    UPDATE pickup_trip SET status = 'IN_PROGRESS', started_at = COALESCE(started_at, NOW())
     WHERE trip_id = p_trip_id;
    UPDATE trip_stop SET arrived_at = COALESCE(arrived_at, NOW()), departed_at = NOW()
     WHERE trip_id = p_trip_id AND stop_seq = p_stop_seq;

    SELECT c.batch_id, c.claim_id, p_trip_id, 'PICKED_UP', p_user_id, p_temperature_c
      FROM trip_item ti JOIN claim c ON c.claim_id = ti.claim_id
     WHERE ti.trip_id = p_trip_id AND ti.pickup_seq = p_stop_seq AND c.status = 'ACTIVE';

    UPDATE surplus_batch b
      JOIN claim c      ON c.batch_id = b.batch_id AND c.status = 'ACTIVE'
      JOIN trip_item ti ON ti.claim_id = c.claim_id
       SET b.status = 'IN_TRANSIT'
     WHERE ti.trip_id = p_trip_id AND ti.pickup_seq = p_stop_seq;
  COMMIT;
END$$

-- ---------------------------------------------------------------------
-- sp_record_delivery : volunteer is at a DROP stop. The shelter's
--   hygiene check result decides the outcome for every claim dropped
--   here: pass -> DELIVERED / FULFILLED, fail -> REJECTED.
--   PERISHABILITY RULE (R9) at the door: food that reaches the shelter
--   after its safe_until time is REJECTED ("arrived after safe-until
--   time") even if the volunteer ticks the hygiene check, so it can never
--   be counted as a meal saved. Same rule as the seed history.
--   When the last stop is done, the trip is COMPLETED.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_record_delivery(IN p_user_id INT UNSIGNED,
                                    IN p_trip_id INT UNSIGNED,
                                    IN p_stop_seq TINYINT UNSIGNED,
                                    IN p_temperature_c DECIMAL(4,1),
                                    IN p_hygiene_ok BOOLEAN,
                                    IN p_notes VARCHAR(255))
SQL SECURITY DEFINER
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF NOT EXISTS (SELECT 1 FROM pickup_trip pt JOIN trip_stop ts ON ts.trip_id = pt.trip_id
                  WHERE pt.trip_id = p_trip_id AND pt.volunteer_id = p_user_id
                    AND pt.status = 'IN_PROGRESS'
                    AND ts.stop_seq = p_stop_seq AND ts.stop_type = 'DROP'
                    AND ts.departed_at IS NULL) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not your open drop stop';
  END IF;

  START TRANSACTION;
    UPDATE trip_stop SET arrived_at = COALESCE(arrived_at, NOW()), departed_at = NOW()
     WHERE trip_id = p_trip_id AND stop_seq = p_stop_seq;

    -- the outcome of each claim dropped here, decided ONCE into a temp
    -- table: pass only if the check passed AND the food is still inside
    -- its safe time. (The claim trigger updates surplus_batch, so the
    -- claim UPDATE below must not read surplus_batch itself: error 1442.)
    DROP TEMPORARY TABLE IF EXISTS tmp_drop_outcome;
    CREATE TEMPORARY TABLE tmp_drop_outcome
    SELECT c.claim_id, c.batch_id,
           (p_hygiene_ok AND b.safe_until > NOW()) AS passed,
           IF(b.safe_until <= NOW(), 'arrived after safe-until time',
              IF(p_hygiene_ok, NULL, COALESCE(p_notes, 'failed hygiene check'))) AS reason
      FROM trip_item ti
      JOIN claim c         ON c.claim_id = ti.claim_id
      JOIN surplus_batch b ON b.batch_id = c.batch_id
     WHERE ti.trip_id = p_trip_id AND ti.drop_seq = p_stop_seq AND c.status = 'ACTIVE';

                               temperature_c, hygiene_ok, notes)
    SELECT o.batch_id, o.claim_id, p_trip_id, 'HYGIENE_CHECK', p_user_id,
           p_temperature_c, o.passed, COALESCE(o.reason, p_notes)
      FROM tmp_drop_outcome o;

    SELECT o.batch_id, o.claim_id, p_trip_id, 'DELIVERED', p_user_id
      FROM tmp_drop_outcome o WHERE o.passed;

    -- claim AU trigger turns these into DELIVERED / CANCELLED batches
    UPDATE claim c JOIN tmp_drop_outcome o ON o.claim_id = c.claim_id
       SET c.status = IF(o.passed, 'FULFILLED', 'REJECTED'),
           c.close_reason = o.reason;
    DROP TEMPORARY TABLE IF EXISTS tmp_drop_outcome;

    UPDATE pickup_trip
       SET status = 'COMPLETED', completed_at = NOW()
     WHERE trip_id = p_trip_id
       AND NOT EXISTS (SELECT 1 FROM trip_stop
                        WHERE trip_id = p_trip_id AND departed_at IS NULL);
  COMMIT;
END$$

-- ---------------------------------------------------------------------
-- sp_set_availability : a volunteer goes on / off duty. Exists so the
-- volunteer role needs no direct UPDATE on the volunteer table (which
-- would let one volunteer change another's row).
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_set_availability(IN p_user_id INT UNSIGNED, IN p_available BOOLEAN)
SQL SECURITY DEFINER
BEGIN
  UPDATE volunteer SET is_available = p_available WHERE user_id = p_user_id;
  IF ROW_COUNT() = 0 AND NOT EXISTS (SELECT 1 FROM volunteer WHERE user_id = p_user_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not a volunteer';
  END IF;
END$$

-- ---------------------------------------------------------------------
-- sp_expire_batches : the AUTO-EXPIRE job (run every 5 min by
--   ev_auto_expire, and once at the end of the seed).
--   1. Live claims whose food expired before pickup are cancelled
--      (trigger releases capacity and marks the batch EXPIRED).
--   2. Remaining AVAILABLE batches past safe_until become EXPIRED
--      (trigger writes the EXPIRED custody event).
--   Step 1 first copies ids into a temporary table: a trigger cannot
--   update surplus_batch while the outer UPDATE statement is reading it
--   (MySQL error 1442), so the outer statement must not read it.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_expire_batches()
SQL SECURITY DEFINER
BEGIN
  DECLARE v_now DATETIME(3) DEFAULT NOW(3);

  DROP TEMPORARY TABLE IF EXISTS tmp_expired_claims;
  CREATE TEMPORARY TABLE tmp_expired_claims (claim_id INT UNSIGNED PRIMARY KEY)
  SELECT c.claim_id
    FROM claim c JOIN surplus_batch b ON b.batch_id = c.batch_id
   WHERE c.status = 'ACTIVE' AND b.status = 'CLAIMED' AND b.safe_until <= v_now;

  UPDATE claim c JOIN tmp_expired_claims x ON x.claim_id = c.claim_id
     SET c.status = 'CANCELLED', c.closed_at = v_now,
         c.close_reason = 'food expired before pickup';

  UPDATE surplus_batch
     SET status = 'EXPIRED'
   WHERE status = 'AVAILABLE' AND safe_until <= v_now;   -- range scan on IDX-4

  DROP TEMPORARY TABLE IF EXISTS tmp_expired_claims;
END$$

-- ---------------------------------------------------------------------
-- sp_generate_forecast : SURPLUS FORECAST + PRE-ALERTS.
--   Method WEEKDAY_MA_4W: for each mess and meal slot, the predicted
--   leftover on p_date is the average leftover on the same weekday in
--   the previous 4 weeks (weekly rhythm of hostel attendance).
--   Simple, explainable, and its accuracy can be measured later by
--   comparing surplus_forecast with mess_meal_log.
--   If p_notify is TRUE, shelters get a FORECAST_PREALERT when a
--   mess/slot is predicted to have >= 10 kg left over. (FALSE is used to
--   back-fill forecasts for past days, to measure forecast accuracy.)
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_generate_forecast(IN p_date DATE, IN p_notify BOOLEAN)
SQL SECURITY DEFINER
BEGIN
  DECLARE c_alert_kg DECIMAL(7,2) DEFAULT 10.00;   -- ASSUMPTION

  SELECT l.mess_site_id, p_date, l.meal_slot, 'WEEKDAY_MA_4W', ROUND(AVG(l.leftover_kg), 2)
    FROM mess_meal_log l
   WHERE l.service_date IN (p_date - INTERVAL 7 DAY,  p_date - INTERVAL 14 DAY,
                            p_date - INTERVAL 21 DAY, p_date - INTERVAL 28 DAY)
     AND l.leftover_kg IS NOT NULL
   GROUP BY l.mess_site_id, l.meal_slot
  ON DUPLICATE KEY UPDATE predicted_kg = VALUES(predicted_kg), generated_at = NOW();

  SELECT u.user_id, 'FORECAST_PREALERT',
         CONCAT('Forecast for ', p_date, ': about ', ROUND(f.total_kg), ' kg surplus expected, peak ',
                f.peak_kg, ' kg at ', f.peak_mess, ' (', f.peak_slot, ')')
    FROM (SELECT SUM(sf.predicted_kg) AS total_kg,
                 MAX(sf.predicted_kg) AS peak_kg,
                 SUBSTRING_INDEX(GROUP_CONCAT(t.name ORDER BY sf.predicted_kg DESC SEPARATOR '#'), '#', 1) AS peak_mess,
                 SUBSTRING_INDEX(GROUP_CONCAT(sf.meal_slot ORDER BY sf.predicted_kg DESC), ',', 1) AS peak_slot
            FROM surplus_forecast sf JOIN site t ON t.site_id = sf.mess_site_id
           WHERE sf.forecast_date = p_date AND sf.method = 'WEEKDAY_MA_4W'
             AND sf.predicted_kg >= c_alert_kg) f
    JOIN app_user u ON u.role = 'SHELTER' AND u.is_active
   WHERE f.total_kg IS NOT NULL AND p_notify;
END$$

-- ---------------------------------------------------------------------
-- sp_explain_my_eligibility : "WHY CAN'T I CLAIM THIS?" for ONE shelter.
--   Answers, for the logged-in shelter user and one batch, which matching
--   rules pass or fail and how each score factor is made up, with the
--   real numbers. It shows ONLY the caller's own shelter: no other
--   shelter's capacity, score or fairness appears anywhere in the output.
--
--   Why a separate procedure: sp_rank_shelters returns EVERY shelter, which
--   a mess admin needs ("who gets this?") but a shelter must not see. The
--   shelter role is therefore granted this procedure and NOT
--   sp_rank_shelters (08_roles_grants.sql), so MySQL itself blocks a
--   shelter from reading the full ranking.
--
--   Row-level ownership: the shelter is resolved from p_user_id inside the
--   procedure (SQL SECURITY DEFINER), exactly like sp_claim_batch. MySQL
--   has no row-level security, so the API passes the logged-in user's id.
--
--   It reuses the same functions as the ranking, so the explanation can
--   never disagree with the real decision:
--     hard rules : status, shelter open (site.is_active), fn_is_diet_compatible (diet), fn_capacity_score
--                  (space left), fn_distance_score (15 km radius),
--                  fn_perishability_score (arrival + 30 min buffer)
--     factors    : fn_need_score, fn_fairness_score, fn_distance_score,
--                  fn_perishability_score, fn_capacity_score, weighted by
--                  scoring_weight; fn_match_score gives the final number.
--
--   Output: one row per check, in reading order.
--     kind        RULE (must pass), FACTOR (part of the score), RESULT
--     code        STATUS, OPEN, DIET, CAPACITY, RADIUS, TIME, NEED, ...
--     label       short name
--     passed      1 / 0 for rules and the result, NULL for factors
--     explanation a plain sentence with this shelter's own numbers
--     score       0-100 for factors and the result
--     weight      the factor's weight from scoring_weight
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_explain_my_eligibility(IN p_user_id INT UNSIGNED, IN p_batch_id INT UNSIGNED)
SQL SECURITY DEFINER
BEGIN
  DECLARE c_radius_km  DECIMAL(5,2) DEFAULT 15.00;   -- same ASSUMPTION as fn_distance_score
  DECLARE c_buffer_min DECIMAL(5,1) DEFAULT 30.0;    -- same ASSUMPTION as fn_perishability_score
  DECLARE v_now     DATETIME DEFAULT NOW();
  DECLARE v_shelter INT UNSIGNED;
  DECLARE v_status  VARCHAR(12);
  DECLARE v_open    BOOLEAN;
  DECLARE v_desc    VARCHAR(200);
  DECLARE v_qty     DECIMAL(7,2);
  DECLARE v_safe    DATETIME;
  DECLARE v_km      DECIMAL(8,3);
  DECLARE v_travel  DECIMAL(8,1);
  DECLARE v_left    DECIMAL(10,1);
  DECLARE v_cap, v_res, v_free DECIMAL(8,2);
  DECLARE v_needed  INT;
  DECLARE v_bad     VARCHAR(255);
  DECLARE v_need, v_fair, v_dist, v_perish, v_capsc, v_score DECIMAL(6,2);
  DECLARE v_mine, v_total, v_benef, v_benef_total DECIMAL(12,2);
  DECLARE w_need, w_fair, w_dist, w_perish, w_cap DECIMAL(5,3);

  -- 1. whose shelter? (the caller's own, never a parameter)
  SELECT site_id INTO v_shelter FROM app_user
   WHERE user_id = p_user_id AND role = 'SHELTER' AND is_active;
  IF v_shelter IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only active shelter staff can ask about their own eligibility';
  END IF;

  -- 2. the batch, and the distance from its mess to THIS shelter
  SELECT b.status, b.description, b.quantity_kg, b.safe_until, fn_distance_km(ms.location, me.location)
    INTO v_status, v_desc, v_qty, v_safe, v_km
    FROM surplus_batch b
    JOIN site ms ON ms.site_id = b.mess_site_id
    JOIN site me ON me.site_id = v_shelter
   WHERE b.batch_id = p_batch_id;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unknown batch';
  END IF;
  SET v_travel = fn_travel_minutes(v_km);
  SET v_left   = TIMESTAMPDIFF(SECOND, v_now, v_safe) / 60;

  -- 3. this shelter's own capacity and need for today, and whether the
  --    shelter is still open (fn_match_score excludes closed shelters)
  SELECT COALESCE(sd.capacity_kg, s.default_capacity_kg), COALESCE(sd.reserved_kg, 0),
         COALESCE(sd.meals_needed, s.beneficiary_count), t.is_active
    INTO v_cap, v_res, v_needed, v_open
    FROM shelter s
    JOIN site t ON t.site_id = s.site_id
    LEFT JOIN shelter_day sd ON sd.shelter_site_id = s.site_id AND sd.day = DATE(v_now)
   WHERE s.site_id = v_shelter;
  SET v_free = v_cap - v_res;

  -- 4. diet: which of the batch's tags are on this shelter's exclusion list
  SELECT GROUP_CONCAT(LOWER(REPLACE(bdt.tag_code, '_', ' ')) ORDER BY bdt.tag_code SEPARATOR ', ')
    INTO v_bad
    FROM batch_diet_tag bdt
    JOIN shelter_diet_exclusion sde ON sde.tag_code = bdt.tag_code
   WHERE bdt.batch_id = p_batch_id AND sde.shelter_site_id = v_shelter;

  -- 5. the same functions the ranking uses
  SET v_need   = fn_need_score(v_shelter, DATE(v_now));
  SET v_fair   = fn_fairness_score(v_shelter, v_now);
  SET v_dist   = fn_distance_score(v_km);
  SET v_perish = fn_perishability_score(v_travel, v_left);
  SET v_capsc  = fn_capacity_score(v_shelter, DATE(v_now), v_qty);
  SET v_score  = fn_match_score(p_batch_id, v_shelter, v_now);

  -- fairness inputs, as totals and shares only (nothing per other shelter)
  SELECT COALESCE(SUM(IF(c.shelter_site_id = v_shelter, b.quantity_kg, 0)), 0), COALESCE(SUM(b.quantity_kg), 0)
    INTO v_mine, v_total
    FROM claim c JOIN surplus_batch b ON b.batch_id = c.batch_id
   WHERE c.status IN ('ACTIVE','FULFILLED')
     AND c.claimed_at >= v_now - INTERVAL 7 DAY AND c.claimed_at < v_now;
  SELECT SUM(IF(s.site_id = v_shelter, s.beneficiary_count, 0)), SUM(s.beneficiary_count)
    INTO v_benef, v_benef_total
    FROM shelter s JOIN site t ON t.site_id = s.site_id WHERE t.is_active;

  SELECT MAX(IF(weight_key = 'NEED', weight_value, NULL)),     MAX(IF(weight_key = 'FAIRNESS', weight_value, NULL)),
         MAX(IF(weight_key = 'DISTANCE', weight_value, NULL)), MAX(IF(weight_key = 'PERISHABILITY', weight_value, NULL)),
         MAX(IF(weight_key = 'CAPACITY', weight_value, NULL))
    INTO w_need, w_fair, w_dist, w_perish, w_cap
    FROM scoring_weight;

  -- 6. one row per check
  SELECT 'RULE' AS kind, 'STATUS' AS code, 'Still available' AS label,
         (v_status = 'AVAILABLE') AS passed,
         IF(v_status = 'AVAILABLE', 'Nobody has claimed this batch yet.',
            CONCAT('This batch is already ', LOWER(v_status), ', so it can no longer be claimed.')) AS explanation,
         NULL AS score, NULL AS weight
  UNION ALL
  SELECT 'RULE', 'OPEN', 'Shelter open', v_open,
         IF(v_open, 'Your shelter is active on the platform.',
            'Your shelter is marked closed on the platform, so it cannot receive food.'), NULL, NULL
  UNION ALL
  SELECT 'RULE', 'DIET', 'Diet', (v_bad IS NULL),
         IF(v_bad IS NULL, 'Nothing in this batch is on your diet exclusion list.',
            CONCAT('This batch is tagged ', v_bad, ', which your shelter has excluded.')), NULL, NULL
  UNION ALL
  SELECT 'RULE', 'CAPACITY', 'Space left today', (v_free >= v_qty),
         CONCAT('This batch is ', FORMAT(v_qty, 1), ' kg; you have ', FORMAT(GREATEST(v_free, 0), 1),
                ' kg of space left today (', FORMAT(v_cap, 1), ' kg capacity, ', FORMAT(v_res, 1),
                ' kg already reserved).',
                IF(v_free >= v_qty, '', ' The whole batch has to fit, so it cannot be claimed.')), NULL, NULL
  UNION ALL
  SELECT 'RULE', 'RADIUS', 'Within 15 km', (v_km <= c_radius_km),
         CONCAT('The mess is ', FORMAT(v_km, 1), ' km from you; the service radius is ',
                FORMAT(c_radius_km, 0), ' km.'), NULL, NULL
  UNION ALL
  SELECT 'RULE', 'TIME', 'Arrives in time', (v_perish IS NOT NULL),
         CONCAT('A trip to you takes about ', ROUND(v_travel), ' min; the food is safe for ',
                GREATEST(ROUND(v_left), 0), ' more min, and a ', ROUND(c_buffer_min),
                '-min safety margin is needed, so the trip must take under ',
                GREATEST(ROUND(v_left - c_buffer_min), 0), ' min.'), NULL, NULL
  UNION ALL
  SELECT 'FACTOR', 'NEED', 'Need', NULL,
         CONCAT('You need ', v_needed, ' meals today; ', ROUND(v_need), '% of them are not covered yet. ',
                'The more you still lack, the higher this is.'), v_need, w_need
  UNION ALL
  SELECT 'FACTOR', 'FAIRNESS', 'Fairness', NULL,
         CONCAT('In the last 7 days you received ', FORMAT(v_mine, 1), ' kg, ',
                IF(v_total = 0, '0', FORMAT(100 * v_mine / v_total, 1)), '% of all food claimed; you serve ',
                IF(v_benef_total = 0, '0', FORMAT(100 * v_benef / v_benef_total, 1)),
                '% of all beneficiaries. Below your share scores higher.'), v_fair, w_fair
  UNION ALL
  SELECT 'FACTOR', 'DISTANCE', 'Distance', NULL,
         CONCAT(FORMAT(v_km, 1), ' km away. Closer is higher; 0 at ', FORMAT(c_radius_km, 0), ' km.'), v_dist, w_dist
  UNION ALL
  SELECT 'FACTOR', 'PERISHABILITY', 'Time margin', NULL,
         CONCAT('The trip would use ', IF(v_left > 0, ROUND(100 * v_travel / v_left), 100),
                '% of the food''s remaining safe time. Less is higher.'), v_perish, w_perish
  UNION ALL
  SELECT 'FACTOR', 'CAPACITY', 'Capacity fit', NULL,
         CONCAT('The batch would fill ', IF(v_free > 0, ROUND(100 * v_qty / v_free), 100),
                '% of your free space. A fuller fit wastes less space and is higher.'), v_capsc, w_cap
  UNION ALL
  SELECT 'RESULT', 'MATCH', 'Your match score', (v_status = 'AVAILABLE' AND v_score IS NOT NULL),
         IF(v_score IS NULL,
            'At least one rule above fails, so you get no score for this batch and cannot claim it.',
            IF(v_status = 'AVAILABLE',
               'Every rule passes: the score is the weighted average of the five factors, and you can claim it.',
               'The rules pass for you, but the batch is no longer available.')),
         v_score, NULL;
END$$

DELIMITER ;

-- >>>>>>>>>>>>>>>>>>>> sql/05_triggers.sql <<<<<<<<<<<<<<<<<<<<

-- =====================================================================
-- MealBridge : TRIGGERS and the auto-expire EVENT        Stage 4 deliverable
-- Run after 04_procedures.sql (the EVENT calls sp_expire_batches).
--
-- Reading guide for the viva. Each trigger enforces a rule that a CHECK
-- constraint cannot, because the rule looks at ANOTHER table or at the
-- OLD value of a row:
--
--   app_user        BI/BU  role must match site type (rule R10)
--   surplus_batch   BI     perishability clock: safe_until snapshot (R9)
--                   AI     custody chain COOKED/PACKED/POSTED + audit
--                   BU     legal status transitions, deadline is frozen
--                   AU     audit + custody EXPIRED / CANCELLED
--   claim           BI     batch must be AVAILABLE, unexpired, diet-safe
--                   AI     CAPACITY UPDATE (shelter_day.reserved_kg),
--                          batch -> CLAIMED, custody CLAIMED, audit
--                   BU     legal claim transitions
--                   AU     release capacity on cancel/reject, batch status
--   custody_event   BI     SHA-256 hash chain (tamper evidence, R8)
--                   BU/BD  append-only: no UPDATE, no DELETE, not even root
--   trip_item       BI     pickup stop = batch's mess, drop = claimant (R10)
--   batch_diet_tag  AD     audit of deleted tags
--   scoring_weight  AU     audit of policy changes
--   food_category   AU     audit of safe-hour / factor changes
--
--   EVENT ev_auto_expire (every 5 minutes) calls sp_expire_batches().
--   A trigger cannot fire "when the clock passes safe_until"; triggers
--   only fire on INSERT/UPDATE/DELETE. So the EVENT is the timer and
--   the batch AU trigger reacts to the status change. Between two runs
--   of the event, trg_claim_bi still refuses expired food and the live
--   feed view hides it, so expired food is never offered (R9).
--
-- Note on audit_log.db_user: inside a trigger CURRENT_USER() returns the
-- trigger's DEFINER, not the person connected. USER() returns the real
-- session login, so the triggers write USER() explicitly.
-- =====================================================================
USE mealbridge;
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;  -- also when run on its own; see 01_schema.sql

DROP TRIGGER IF EXISTS trg_user_bi;
DROP TRIGGER IF EXISTS trg_user_bu;
DROP TRIGGER IF EXISTS trg_user_au;
DROP TRIGGER IF EXISTS trg_batch_bi;
DROP TRIGGER IF EXISTS trg_batch_ai;
DROP TRIGGER IF EXISTS trg_batch_bu;
DROP TRIGGER IF EXISTS trg_batch_au;
DROP TRIGGER IF EXISTS trg_claim_bi;
DROP TRIGGER IF EXISTS trg_claim_ai;
DROP TRIGGER IF EXISTS trg_claim_bu;
DROP TRIGGER IF EXISTS trg_claim_au;
DROP TRIGGER IF EXISTS trg_custody_bi;
DROP TRIGGER IF EXISTS trg_custody_bu;
DROP TRIGGER IF EXISTS trg_custody_bd;
DROP TRIGGER IF EXISTS trg_trip_item_bi;
DROP TRIGGER IF EXISTS trg_bdt_ad;
DROP TRIGGER IF EXISTS trg_weight_au;
DROP TRIGGER IF EXISTS trg_category_au;
DROP EVENT   IF EXISTS ev_auto_expire;

DELIMITER $$

-- =====================================================================
-- APP_USER : a MESS_ADMIN must point at a MESS site, a SHELTER user at a
-- SHELTER site. (The CHECK in the table only knows whether site_id is
-- NULL; the site's type lives in another table.)
-- =====================================================================
CREATE TRIGGER trg_user_bi BEFORE INSERT ON app_user FOR EACH ROW
BEGIN
  IF NEW.role = 'MESS_ADMIN'
     AND NOT EXISTS (SELECT 1 FROM mess WHERE site_id = NEW.site_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R10: a MESS_ADMIN must belong to a MESS site';
  END IF;
  IF NEW.role = 'SHELTER'
     AND NOT EXISTS (SELECT 1 FROM shelter WHERE site_id = NEW.site_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R10: a SHELTER user must belong to a SHELTER site';
  END IF;
END$$

CREATE TRIGGER trg_user_bu BEFORE UPDATE ON app_user FOR EACH ROW
BEGIN
  IF NEW.role = 'MESS_ADMIN'
     AND NOT EXISTS (SELECT 1 FROM mess WHERE site_id = NEW.site_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R10: a MESS_ADMIN must belong to a MESS site';
  END IF;
  IF NEW.role = 'SHELTER'
     AND NOT EXISTS (SELECT 1 FROM shelter WHERE site_id = NEW.site_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R10: a SHELTER user must belong to a SHELTER site';
  END IF;
END$$

-- Audit role / activation changes. The password hash is deliberately
-- NOT copied into the audit log.
CREATE TRIGGER trg_user_au AFTER UPDATE ON app_user FOR EACH ROW
BEGIN
  IF NOT (OLD.role <=> NEW.role) OR NOT (OLD.site_id <=> NEW.site_id)
     OR NOT (OLD.is_active <=> NEW.is_active) THEN
    VALUES ('app_user', NEW.user_id, 'UPDATE', USER(),
            JSON_OBJECT('role', OLD.role, 'site_id', OLD.site_id, 'is_active', OLD.is_active),
            JSON_OBJECT('role', NEW.role, 'site_id', NEW.site_id, 'is_active', NEW.is_active));
  END IF;
END$$

-- =====================================================================
-- SURPLUS_BATCH
-- =====================================================================

-- BI : the perishability clock. Whatever safe_until the client sent is
-- overwritten, so no client can extend a deadline. Also: the poster must
-- be a MESS_ADMIN of THIS mess.
CREATE TRIGGER trg_batch_bi BEFORE INSERT ON surplus_batch FOR EACH ROW
BEGIN
  IF NOT EXISTS (SELECT 1 FROM app_user
                  WHERE user_id = NEW.posted_by AND is_active
                    AND ( (role = 'MESS_ADMIN' AND site_id = NEW.mess_site_id)
                       OR  role = 'PLATFORM_ADMIN')) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Batch must be posted by an active admin of this mess';
  END IF;
  SET NEW.created_at = COALESCE(NEW.created_at, NOW());
  SET NEW.safe_until = fn_safe_until(NEW.category_id, NEW.storage, NEW.cooked_at);
  IF NEW.safe_until <= NEW.created_at THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'R9: food is already past its safe-until time, it cannot be posted';
  END IF;
  SET NEW.status = 'AVAILABLE';            -- every batch starts life available
END$$

-- AI : start the chain of custody and write the audit row.
CREATE TRIGGER trg_batch_ai AFTER INSERT ON surplus_batch FOR EACH ROW
BEGIN
  VALUES (NEW.batch_id, 'COOKED', NEW.cooked_at, NEW.posted_by, NULL);
  IF NEW.packed_at IS NOT NULL THEN
    VALUES (NEW.batch_id, 'PACKED', NEW.packed_at, NEW.posted_by, NULL);
  END IF;
  VALUES (NEW.batch_id, 'POSTED', NEW.created_at, NEW.posted_by,
          CONCAT(NEW.quantity_kg, ' kg, safe until ', NEW.safe_until));

  VALUES ('surplus_batch', NEW.batch_id, 'INSERT', USER(), NEW.created_at,
          JSON_OBJECT('mess', NEW.mess_site_id, 'category', NEW.category_id,
                      'qty_kg', NEW.quantity_kg, 'storage', NEW.storage,
                      'safe_until', NEW.safe_until, 'status', NEW.status));
END$$

-- BU : state machine of a batch + frozen fields.
--   AVAILABLE  -> CLAIMED | EXPIRED | CANCELLED
--   CLAIMED    -> AVAILABLE (claim cancelled) | IN_TRANSIT | EXPIRED | CANCELLED
--   IN_TRANSIT -> DELIVERED | CANCELLED (rejected at the door)
--   DELIVERED, EXPIRED, CANCELLED are final.
CREATE TRIGGER trg_batch_bu BEFORE UPDATE ON surplus_batch FOR EACH ROW
BEGIN
  IF NOT (NEW.safe_until <=> OLD.safe_until) OR NOT (NEW.cooked_at <=> OLD.cooked_at)
     OR NOT (NEW.category_id <=> OLD.category_id) OR NOT (NEW.storage <=> OLD.storage) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Deadline inputs (cooked_at, category, storage, safe_until) are frozen once posted';
  END IF;
  IF NEW.quantity_kg <> OLD.quantity_kg AND OLD.status <> 'AVAILABLE' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Quantity cannot change after the batch is claimed';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
       (OLD.status = 'AVAILABLE'  AND NEW.status IN ('CLAIMED','EXPIRED','CANCELLED'))
    OR (OLD.status = 'CLAIMED'    AND NEW.status IN ('AVAILABLE','IN_TRANSIT','EXPIRED','CANCELLED'))
    OR (OLD.status = 'IN_TRANSIT' AND NEW.status IN ('DELIVERED','CANCELLED'))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Illegal batch status transition';
  END IF;
END$$

-- AU : audit every change; status changes that end a batch's life are
-- also written to the chain of custody.
CREATE TRIGGER trg_batch_au AFTER UPDATE ON surplus_batch FOR EACH ROW
BEGIN
  VALUES ('surplus_batch', NEW.batch_id, 'UPDATE', USER(),
          JSON_OBJECT('status', OLD.status, 'qty_kg', OLD.quantity_kg, 'description', OLD.description),
          JSON_OBJECT('status', NEW.status, 'qty_kg', NEW.quantity_kg, 'description', NEW.description));

  IF NEW.status = 'EXPIRED' AND OLD.status <> 'EXPIRED' THEN
    -- event time = the real deadline, not the moment the job noticed it
    VALUES (NEW.batch_id, 'EXPIRED', NEW.safe_until, 'auto-expired: safe-until time passed');
  ELSEIF NEW.status = 'CANCELLED' AND OLD.status = 'AVAILABLE' THEN
    VALUES (NEW.batch_id, 'CANCELLED', 'withdrawn by mess');
  END IF;
END$$

-- =====================================================================
-- CLAIM
-- =====================================================================

-- BI : the claim must make sense against the batch and the shelter.
-- (Concurrency is handled by the FOR UPDATE lock in sp_claim_batch and
-- by the UNIQUE index on active_batch_id; this trigger checks business
-- validity.)
CREATE TRIGGER trg_claim_bi BEFORE INSERT ON claim FOR EACH ROW
BEGIN
  DECLARE v_status VARCHAR(12);
  DECLARE v_safe_until DATETIME;

  SET NEW.claimed_at = COALESCE(NEW.claimed_at, NOW(3));

  SELECT status, safe_until INTO v_status, v_safe_until
    FROM surplus_batch WHERE batch_id = NEW.batch_id;

  IF v_status <> 'AVAILABLE' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R5: batch is not AVAILABLE (already claimed or closed)';
  END IF;
  IF NEW.claimed_at >= v_safe_until THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R9: batch has passed its safe-until time';
  END IF;
  IF NOT fn_is_diet_compatible(NEW.batch_id, NEW.shelter_site_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Batch contains an item this shelter excludes';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM app_user
                  WHERE user_id = NEW.claimed_by AND is_active
                    AND ( (role = 'SHELTER' AND site_id = NEW.shelter_site_id)
                       OR  role = 'PLATFORM_ADMIN')) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Claim must be made by staff of the claiming shelter';
  END IF;
  -- a new claim is always live; it can only be closed by an UPDATE
  SET NEW.status = 'ACTIVE', NEW.closed_at = NULL, NEW.close_reason = NULL;
END$$

-- AI : CAPACITY UPDATE. Adds the batch's kg to the shelter's reserved_kg
-- for the claim's day (creating the day row from the shelter's defaults
-- if it does not exist). If this would exceed capacity_kg, the CHECK
-- chk_sd_reserved fails, and MySQL rolls back the WHOLE statement,
-- including the claim row itself. So over-allocation is impossible.
CREATE TRIGGER trg_claim_ai AFTER INSERT ON claim FOR EACH ROW
BEGIN
  DECLARE v_qty DECIMAL(7,2);
  SELECT quantity_kg INTO v_qty FROM surplus_batch WHERE batch_id = NEW.batch_id;

  -- UPDATE first, INSERT only if the day row is missing. (INSERT ... ON
  -- DUPLICATE KEY UPDATE would not work: MySQL checks the CHECK
  -- constraint on the row it TRIES to insert, with default capacity,
  -- before it notices the duplicate key and switches to the update.)
  UPDATE shelter_day
     SET reserved_kg = reserved_kg + v_qty
   WHERE shelter_site_id = NEW.shelter_site_id AND day = DATE(NEW.claimed_at);
  IF ROW_COUNT() = 0 THEN
    SELECT s.site_id, DATE(NEW.claimed_at), s.beneficiary_count, s.default_capacity_kg, v_qty
      FROM shelter s WHERE s.site_id = NEW.shelter_site_id;
  END IF;

  UPDATE surplus_batch SET status = 'CLAIMED' WHERE batch_id = NEW.batch_id;

  VALUES (NEW.batch_id, NEW.claim_id, 'CLAIMED', NEW.claimed_at, NEW.claimed_by,
          CONCAT('shelter ', NEW.shelter_site_id, ', score ', NEW.match_score,
                 ', ', NEW.distance_km, ' km'));

  VALUES ('claim', NEW.claim_id, 'INSERT', USER(), NEW.claimed_at,
          JSON_OBJECT('batch', NEW.batch_id, 'shelter', NEW.shelter_site_id,
                      'score', NEW.match_score, 'km', NEW.distance_km));
END$$

-- BU : a claim may only move ACTIVE -> FULFILLED | CANCELLED | REJECTED,
-- and a claim cannot be "cancelled" once the food is on the road (that
-- is a REJECTED at the door instead).
CREATE TRIGGER trg_claim_bu BEFORE UPDATE ON claim FOR EACH ROW
BEGIN
  IF NEW.batch_id <> OLD.batch_id OR NEW.shelter_site_id <> OLD.shelter_site_id
     OR NEW.match_score <> OLD.match_score OR NEW.distance_km <> OLD.distance_km THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Claim snapshot fields are read-only';
  END IF;
  IF NEW.status <> OLD.status THEN
    IF OLD.status <> 'ACTIVE' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only an ACTIVE claim can change status';
    END IF;
    IF NEW.status = 'CANCELLED' AND EXISTS (SELECT 1 FROM surplus_batch
                       WHERE batch_id = NEW.batch_id AND status = 'IN_TRANSIT') THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Food already picked up: use REJECTED, not CANCELLED';
    END IF;
    SET NEW.closed_at = COALESCE(NEW.closed_at, NOW(3));
  END IF;
END$$

-- AU : keep shelter capacity and batch status in step with the claim.
CREATE TRIGGER trg_claim_au AFTER UPDATE ON claim FOR EACH ROW
BEGIN
  DECLARE v_qty DECIMAL(7,2);
  DECLARE v_safe_until DATETIME;

  IF NEW.status <> OLD.status THEN
    SELECT quantity_kg, safe_until INTO v_qty, v_safe_until
      FROM surplus_batch WHERE batch_id = NEW.batch_id;

    IF NEW.status IN ('CANCELLED','REJECTED') THEN
      -- CAPACITY UPDATE: give the reserved kilograms back to the shelter
      UPDATE shelter_day
         SET reserved_kg = reserved_kg - v_qty
       WHERE shelter_site_id = NEW.shelter_site_id AND day = DATE(NEW.claimed_at);
    END IF;

    IF NEW.status = 'FULFILLED' THEN
      UPDATE surplus_batch SET status = 'DELIVERED' WHERE batch_id = NEW.batch_id;
    ELSEIF NEW.status = 'REJECTED' THEN
      -- refused at the door (e.g. failed hygiene check): food is discarded
      UPDATE surplus_batch SET status = 'CANCELLED' WHERE batch_id = NEW.batch_id;
      VALUES (NEW.batch_id, NEW.claim_id, 'REJECTED', NEW.closed_at, NEW.close_reason);
    ELSEIF NEW.status = 'CANCELLED' THEN
      -- shelter backed out before pickup: offer the food again if still safe
      VALUES (NEW.batch_id, NEW.claim_id, 'CANCELLED', NEW.closed_at,
              CONCAT('claim cancelled: ', IFNULL(NEW.close_reason, '-')));
      UPDATE surplus_batch
         SET status = IF(v_safe_until > NEW.closed_at, 'AVAILABLE', 'EXPIRED')
       WHERE batch_id = NEW.batch_id;
    END IF;

    VALUES ('claim', NEW.claim_id, 'UPDATE', USER(), NEW.closed_at,
            JSON_OBJECT('status', OLD.status),
            JSON_OBJECT('status', NEW.status, 'reason', NEW.close_reason));
  END IF;
END$$

-- =====================================================================
-- CUSTODY_EVENT : append-only, hash-chained.
--   row_hash = SHA-256( previous row_hash of this batch (or 'GENESIS')
--                       | this row's fields )
--   Changing any old row changes its hash, so every later row's
--   prev_hash no longer matches: fn_custody_first_bad_event finds it.
-- =====================================================================
CREATE TRIGGER trg_custody_bi BEFORE INSERT ON custody_event FOR EACH ROW
BEGIN
  SET NEW.event_time = COALESCE(NEW.event_time, NOW(3));
  -- latest event of the same batch: one backward dive on IDX-12 / PK
  SET NEW.prev_hash = (SELECT row_hash FROM custody_event
                        WHERE batch_id = NEW.batch_id
                        ORDER BY event_id DESC LIMIT 1);
  SET NEW.row_hash = SHA2(CONCAT(IFNULL(NEW.prev_hash,'GENESIS'), '|',
        CONCAT_WS('|', NEW.batch_id, IFNULL(NEW.claim_id,'-'), IFNULL(NEW.trip_id,'-'),
                  NEW.event_type, DATE_FORMAT(NEW.event_time,'%Y-%m-%d %H:%i:%s.%f'),
                  IFNULL(NEW.actor_user_id,'-'), IFNULL(NEW.temperature_c,'-'),
                  IFNULL(NEW.hygiene_ok,'-'), IFNULL(NEW.notes,'-'))), 256);
END$$

CREATE TRIGGER trg_custody_bu BEFORE UPDATE ON custody_event FOR EACH ROW
BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R8: custody_event is append-only (UPDATE refused)';
END$$

CREATE TRIGGER trg_custody_bd BEFORE DELETE ON custody_event FOR EACH ROW
BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R8: custody_event is append-only (DELETE refused)';
END$$

-- =====================================================================
-- TRIP_ITEM : the pickup stop must be at the batch's mess and the drop
-- stop at the claiming shelter (spans trip_stop, claim, surplus_batch).
-- =====================================================================
CREATE TRIGGER trg_trip_item_bi BEFORE INSERT ON trip_item FOR EACH ROW
BEGIN
  IF NOT EXISTS (
      SELECT 1 FROM trip_stop ts
        JOIN claim c         ON c.claim_id = NEW.claim_id
        JOIN surplus_batch b ON b.batch_id = c.batch_id
       WHERE ts.trip_id = NEW.trip_id AND ts.stop_seq = NEW.pickup_seq
         AND ts.stop_type = 'PICKUP' AND ts.site_id = b.mess_site_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R10: pickup stop is not the batch''s mess';
  END IF;
  IF NOT EXISTS (
      SELECT 1 FROM trip_stop ts
        JOIN claim c ON c.claim_id = NEW.claim_id
       WHERE ts.trip_id = NEW.trip_id AND ts.stop_seq = NEW.drop_seq
         AND ts.stop_type = 'DROP' AND ts.site_id = c.shelter_site_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R10: drop stop is not the claiming shelter';
  END IF;
END$$

-- =====================================================================
-- Generic audit of small but important tables
-- =====================================================================
CREATE TRIGGER trg_bdt_ad AFTER DELETE ON batch_diet_tag FOR EACH ROW
BEGIN
  VALUES ('batch_diet_tag', CONCAT(OLD.batch_id, '/', OLD.tag_code), 'DELETE', USER(),
          JSON_OBJECT('batch_id', OLD.batch_id, 'tag', OLD.tag_code));
END$$

CREATE TRIGGER trg_weight_au AFTER UPDATE ON scoring_weight FOR EACH ROW
BEGIN
  VALUES ('scoring_weight', NEW.weight_key, 'UPDATE', USER(),
          JSON_OBJECT('weight', OLD.weight_value), JSON_OBJECT('weight', NEW.weight_value));
END$$

CREATE TRIGGER trg_category_au AFTER UPDATE ON food_category FOR EACH ROW
BEGIN
  VALUES ('food_category', NEW.category_id, 'UPDATE', USER(),
          JSON_OBJECT('ambient', OLD.safe_hours_ambient, 'hot', OLD.safe_hours_hot_held,
                      'chilled', OLD.safe_hours_chilled, 'co2e', OLD.co2e_kg_per_kg),
          JSON_OBJECT('ambient', NEW.safe_hours_ambient, 'hot', NEW.safe_hours_hot_held,
                      'chilled', NEW.safe_hours_chilled, 'co2e', NEW.co2e_kg_per_kg));
END$$

-- =====================================================================
-- EVENT : the auto-expire timer. Needs event_scheduler=ON (MySQL 8
-- default). Calls sp_expire_batches from 04_procedures.sql.
-- =====================================================================
CREATE EVENT ev_auto_expire
  ON SCHEDULE EVERY 5 MINUTE
  COMMENT 'Auto-expire batches whose safe_until has passed'
  DO CALL sp_expire_batches()$$

DELIMITER ;

-- >>>>>>>>>>>>>>>>>>>> sql/06_views.sql <<<<<<<<<<<<<<<<<<<<

-- =====================================================================
-- MealBridge : VIEWS for the live feed, the impact dashboard and the volunteer pickup queue
-- Stage 4 deliverable. Run after 05_triggers.sql.
--
-- Reading guide for the viva:
--   * A view is a stored SELECT. The dashboard reads ONLY these views,
--     so every number on screen has one SQL definition you can show.
--   * Layering: v_batch_outcome computes per-batch facts once; the
--     impact, response-time and leaderboard views aggregate it.
--   * Roles get SELECT on views without SELECT on the base tables
--     (07_roles_grants.sql). Views run with SQL SECURITY DEFINER by
--     default, which is what makes that work.
--   * "Carbon avoided" multiplies delivered kg by food_category.co2e_kg_per_kg.
--     The seed uses ONE global average factor (FAO 2013); see the
--     values_source column. If a factor is NULL the result is NULL,
--     never a guessed number.
-- =====================================================================
USE mealbridge;
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;  -- also when run on its own; see 01_schema.sql

-- ---------------------------------------------------------------------
-- v_live_feed : what a shelter sees right now. Only AVAILABLE batches
-- whose deadline has not passed (so expired food is never offered even
-- between two runs of the auto-expire job). Uses IDX-4 (status, safe_until).
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_live_feed AS
SELECT b.batch_id,
       t.name                                   AS mess,
       fc.name                                  AS category,
       b.description,
       b.quantity_kg,
       fn_meals(b.quantity_kg, b.category_id)   AS meals_equiv,
       b.storage,
       (SELECT GROUP_CONCAT(tag_code ORDER BY tag_code)
          FROM batch_diet_tag d WHERE d.batch_id = b.batch_id) AS diet_tags,
       b.created_at                             AS posted_at,
       b.safe_until,
       TIMESTAMPDIFF(MINUTE, NOW(), b.safe_until) AS minutes_left
  FROM surplus_batch b
  JOIN site t           ON t.site_id = b.mess_site_id
  JOIN food_category fc ON fc.category_id = b.category_id
 WHERE b.status = 'AVAILABLE'
   AND b.safe_until > NOW();

-- ---------------------------------------------------------------------
-- v_batch_outcome : one row per batch with everything the impact
-- reports need. The live/fulfilled claim is found through the UNIQUE
-- generated column claim.active_batch_id (at most one per batch).
--   response_min = minutes from posting to the FIRST claim
--   delivery_min = minutes from posting to the DELIVERED custody event
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_batch_outcome AS
SELECT b.batch_id,
       b.mess_site_id,
       t.name                                   AS mess,
       DATE(b.created_at)                       AS day,
       b.created_at,
       b.meal_slot,
       fc.name                                  AS category,
       b.quantity_kg,
       b.status,
       c.shelter_site_id                        AS delivered_to,
       IF(b.status = 'DELIVERED', b.quantity_kg, 0)                          AS kg_delivered,
       IF(b.status = 'DELIVERED', fn_meals(b.quantity_kg, b.category_id), 0) AS meals_saved,
       IF(b.status = 'DELIVERED', b.quantity_kg * fc.co2e_kg_per_kg, 0)      AS co2e_avoided_kg,
       IF(b.status = 'EXPIRED', b.quantity_kg, 0)                            AS kg_expired,
       TIMESTAMPDIFF(MINUTE, b.created_at,
         (SELECT MIN(c2.claimed_at) FROM claim c2 WHERE c2.batch_id = b.batch_id)) AS response_min,
       TIMESTAMPDIFF(MINUTE, b.created_at,
         (SELECT MAX(e.event_time) FROM custody_event e
           WHERE e.batch_id = b.batch_id AND e.event_type = 'DELIVERED'))   AS delivery_min
  FROM surplus_batch b
  JOIN site t           ON t.site_id = b.mess_site_id
  JOIN food_category fc ON fc.category_id = b.category_id
  LEFT JOIN claim c     ON c.active_batch_id = b.batch_id;

-- ---------------------------------------------------------------------
-- v_impact_daily : the dashboard's time series (one row per day).
--   rescue_rate_pct = kg delivered / kg posted
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_impact_daily AS
SELECT day,
       COUNT(*)                                   AS batches_posted,
       SUM(quantity_kg)                           AS kg_posted,
       SUM(kg_delivered)                          AS kg_delivered,
       SUM(meals_saved)                           AS meals_saved,
       ROUND(SUM(co2e_avoided_kg), 1)             AS co2e_avoided_kg,
       SUM(kg_expired)                            AS kg_expired,
       ROUND(100 * SUM(kg_delivered) / SUM(quantity_kg), 1) AS rescue_rate_pct
  FROM v_batch_outcome
 GROUP BY day;

-- ---------------------------------------------------------------------
-- v_impact_summary : the headline counters (one row).
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_impact_summary AS
SELECT MIN(day)                                   AS from_day,
       MAX(day)                                   AS to_day,
       COUNT(*)                                   AS batches_posted,
       SUM(status = 'DELIVERED')                  AS batches_delivered,
       SUM(meals_saved)                           AS meals_saved,
       SUM(kg_delivered)                          AS kg_diverted,
       ROUND(SUM(co2e_avoided_kg), 0)             AS co2e_avoided_kg,
       SUM(kg_expired)                            AS kg_expired,
       ROUND(100 * SUM(kg_delivered) / SUM(quantity_kg), 1) AS rescue_rate_pct,
       ROUND(AVG(response_min), 0)                AS avg_response_min,
       ROUND(AVG(delivery_min), 0)                AS avg_post_to_delivery_min
  FROM v_batch_outcome;

-- ---------------------------------------------------------------------
-- v_response_time : how fast each shelter responds and receives food.
--   median_response_min uses ROW_NUMBER() and COUNT() OVER () because
--   MySQL has no MEDIAN() aggregate: the median is the middle row(s).
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_response_time AS
WITH r AS (
  SELECT c.shelter_site_id,
         TIMESTAMPDIFF(MINUTE, b.created_at, c.claimed_at) AS response_min,
         ROW_NUMBER() OVER (PARTITION BY c.shelter_site_id
                            ORDER BY TIMESTAMPDIFF(SECOND, b.created_at, c.claimed_at)) AS rn,
         COUNT(*)     OVER (PARTITION BY c.shelter_site_id) AS n
    FROM claim c JOIN surplus_batch b ON b.batch_id = c.batch_id
)
SELECT t.name                                   AS shelter,
       MAX(r.n)                                 AS claims,
       ROUND(AVG(r.response_min), 0)            AS avg_response_min,
       ROUND(AVG(CASE WHEN r.rn IN (FLOOR((r.n + 1) / 2), CEIL((r.n + 1) / 2))
                      THEN r.response_min END), 0) AS median_response_min,
       MIN(r.response_min)                      AS fastest_min,
       MAX(r.response_min)                      AS slowest_min
  FROM r JOIN site t ON t.site_id = r.shelter_site_id
 GROUP BY t.name;

-- ---------------------------------------------------------------------
-- v_shelter_fairness : is food shared in proportion to need?
--   Over the last 30 days, per shelter:
--     need_share_pct      = beneficiaries / all beneficiaries
--     received_share_pct  = kg received / all kg delivered
--     kg_per_beneficiary  = kg received / beneficiaries
--     fair_ratio          = received_share / need_share  (1.00 = fair)
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_shelter_fairness AS
WITH recv AS (
  SELECT s.site_id, t.name, s.beneficiary_count,
         COALESCE(SUM(b.quantity_kg), 0) AS kg_received,
         COUNT(b.batch_id)               AS batches
    FROM shelter s
    JOIN site t ON t.site_id = s.site_id
    LEFT JOIN claim c ON c.shelter_site_id = s.site_id AND c.status = 'FULFILLED'
                     AND c.claimed_at >= NOW() - INTERVAL 30 DAY
    LEFT JOIN surplus_batch b ON b.batch_id = c.batch_id
   WHERE t.is_active
   GROUP BY s.site_id, t.name, s.beneficiary_count
)
SELECT name                                                     AS shelter,
       beneficiary_count                                        AS beneficiaries,
       batches,
       kg_received,
       ROUND(kg_received / beneficiary_count, 2)                AS kg_per_beneficiary,
       ROUND(100 * beneficiary_count / SUM(beneficiary_count) OVER (), 1) AS need_share_pct,
       ROUND(100 * kg_received / NULLIF(SUM(kg_received) OVER (), 0), 1)  AS received_share_pct,
       ROUND((kg_received / NULLIF(SUM(kg_received) OVER (), 0))
             / (beneficiary_count / SUM(beneficiary_count) OVER ()), 2)   AS fair_ratio
  FROM recv;

-- ---------------------------------------------------------------------
-- v_fairness_index : ONE number for the fairness chart.
--   Jain's fairness index (Jain, Chiu & Hawe, 1984) over
--   x_i = kg per beneficiary of shelter i:
--        J = (sum x_i)^2 / (n * sum x_i^2)
--   J = 1.00 when every shelter gets the same kg per beneficiary,
--   J = 1/n when one shelter gets everything.
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_fairness_index AS
SELECT COUNT(*)                                                   AS shelters,
       ROUND(POW(SUM(kg_per_beneficiary), 2)
             / (COUNT(*) * SUM(POW(kg_per_beneficiary, 2))), 3)   AS jain_index,
       ROUND(1 / COUNT(*), 3)                                     AS worst_possible
  FROM v_shelter_fairness;

-- ---------------------------------------------------------------------
-- v_mess_leaderboard : which messes post most and how much is rescued.
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_mess_leaderboard AS
SELECT mess,
       COUNT(*)                                             AS batches,
       SUM(quantity_kg)                                     AS kg_posted,
       SUM(kg_delivered)                                    AS kg_rescued,
       ROUND(100 * SUM(kg_delivered) / SUM(quantity_kg), 1) AS rescue_rate_pct,
       RANK() OVER (ORDER BY SUM(kg_delivered) DESC)        AS rank_by_kg_rescued
  FROM v_batch_outcome
 GROUP BY mess;

-- ---------------------------------------------------------------------
-- v_pickup_queue : (Stage 6) what a VOLUNTEER needs to plan a trip.
--   Claims that are ACTIVE, whose batch is CLAIMED (not yet picked up),
--   still safe, and not already on a PLANNED / IN_PROGRESS trip.
--   Least privilege: the volunteer role has NO SELECT on claim or
--   shelter_day. This view exposes only the columns routing needs
--   (where, how much, until when); match scores and capacity stay hidden.
--   Coordinates are returned as numbers for the map (SRID 4326 order
--   is latitude, longitude).
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_pickup_queue AS
SELECT c.claim_id,
       b.batch_id,
       b.description,
       b.quantity_kg,
       b.safe_until,
       TIMESTAMPDIFF(MINUTE, NOW(), b.safe_until) AS minutes_left,
       ms.site_id                       AS mess_id,
       ms.name                          AS mess,
       ST_Latitude(ms.location)         AS mess_lat,
       ST_Longitude(ms.location)        AS mess_lon,
       ss.site_id                       AS shelter_id,
       ss.name                          AS shelter,
       ST_Latitude(ss.location)         AS shelter_lat,
       ST_Longitude(ss.location)        AS shelter_lon
  FROM claim c
  JOIN surplus_batch b ON b.batch_id = c.batch_id
  JOIN site ms         ON ms.site_id = b.mess_site_id
  JOIN site ss         ON ss.site_id = c.shelter_site_id
 WHERE c.status = 'ACTIVE'
   AND b.status = 'CLAIMED'
   AND b.safe_until > NOW()
   AND NOT EXISTS (SELECT 1
                     FROM trip_item ti
                     JOIN pickup_trip pt ON pt.trip_id = ti.trip_id
                    WHERE ti.claim_id = c.claim_id
                      AND pt.status IN ('PLANNED','IN_PROGRESS'));

-- ---------------------------------------------------------------------
-- v_trip_manifest : (Stage 6) what is on each trip: which batch is
--   loaded at which stop and dropped at which stop. Like v_pickup_queue
--   it lets the volunteer role see a trip's load without SELECT on claim.
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_trip_manifest AS
SELECT ti.trip_id,
       ti.claim_id,
       c.batch_id,
       b.description,
       b.quantity_kg,
       b.status       AS batch_status,
       b.safe_until,
       ti.pickup_seq,
       ti.drop_seq
  FROM trip_item ti
  JOIN claim c         ON c.claim_id = ti.claim_id
  JOIN surplus_batch b ON b.batch_id = c.batch_id;

-- >>>>>>>>>>>>>>>>>>>> sql/07_seed_synthetic.sql <<<<<<<<<<<<<<<<<<<<

-- =====================================================================
-- MealBridge : SYNTHETIC SEED DATA            (generated, do not edit)
-- Generator: tools/gen_seed.py  (random seed 302, deterministic)
--
-- *** ALL DATA IN THIS FILE IS SYNTHETIC. ***  Names start with 'SYN',
-- e-mails use example.org, phones are dummies; every user's password is
-- the demo password 'demo1234' (bcrypt-hashed). DEMO ONLY.
-- Food safe-hours are planning values marked TO VERIFY (see
-- food_category.values_source). Statistics computed from this data
-- demonstrate the queries; they are NOT evidence about real messes.
--
-- Timeline: @d0 = the Monday on or before 30 days ago. History runs to yesterday,
-- replayed in time order through the real functions and triggers;
-- 'today' is created with the live procedures (sp_post_batch, ...).
-- =====================================================================
USE mealbridge;
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;  -- also when run on its own; see 01_schema.sql
SET SESSION max_sp_recursion_depth = 2;   -- seed_trip falls back to single-batch trips
-- the Monday on or before 30 days ago, so day 5 and 6 of each week are real weekends
SET @d0 = CURRENT_DATE - INTERVAL 30 DAY - INTERVAL WEEKDAY(CURRENT_DATE - INTERVAL 30 DAY) DAY;

-- ---------- reference data ----------

-- ---------- users (demo password demo1234, bcrypt) ----------

-- ---------- shelter_day: need and capacity per day (covers history, today, tomorrow) ----------

-- ---------- mess_meal_log and mess_menu (~30 days) ----------

-- ---------- seed-only helper procedures (dropped at the end) ----------
-- They replay history at a GIVEN time. The live procedures always use
-- NOW(), which is why these separate helpers exist.
DELIMITER $$
-- A shelter responds at p_at: picks the p_pick-th best ELIGIBLE shelter
-- by fn_match_score (shelters that already claimed and cancelled this
-- batch are skipped). Does nothing if no shelter is eligible.
CREATE PROCEDURE seed_claim(p_batch INT UNSIGNED, p_at DATETIME, p_pick INT)
proc: BEGIN
  DECLARE v_shelter INT UNSIGNED; DECLARE v_score DECIMAL(5,2); DECLARE v_km DECIMAL(8,3);
  IF p_at >= NOW() OR NOT EXISTS (SELECT 1 FROM surplus_batch WHERE batch_id = p_batch) THEN
    LEAVE proc;     -- history stops before the load time
  END IF;
  IF (SELECT status FROM surplus_batch WHERE batch_id = p_batch) <> 'AVAILABLE'
     OR (SELECT safe_until FROM surplus_batch WHERE batch_id = p_batch) <= p_at THEN
    LEAVE proc;
  END IF;
  SELECT shelter_id, score INTO v_shelter, v_score FROM (
    SELECT s.site_id AS shelter_id, fn_match_score(p_batch, s.site_id, p_at) AS score
      FROM shelter s
     WHERE NOT EXISTS (SELECT 1 FROM claim c WHERE c.batch_id = p_batch AND c.shelter_site_id = s.site_id)) r
   WHERE score IS NOT NULL
   ORDER BY score DESC, shelter_id
   LIMIT 1 OFFSET 0;
  IF p_pick > 1 THEN   -- second-best shelter answered first, if there is one
    SELECT shelter_id, score INTO v_shelter, v_score FROM (
      SELECT s.site_id AS shelter_id, fn_match_score(p_batch, s.site_id, p_at) AS score
        FROM shelter s
       WHERE NOT EXISTS (SELECT 1 FROM claim c WHERE c.batch_id = p_batch AND c.shelter_site_id = s.site_id)) r
     WHERE score IS NOT NULL
     ORDER BY score DESC, shelter_id
     LIMIT 1 OFFSET 1;
  END IF;
  IF v_shelter IS NULL THEN LEAVE proc; END IF;
  SELECT fn_distance_km(ms.location, ss.location) INTO v_km
    FROM surplus_batch b JOIN site ms ON ms.site_id = b.mess_site_id JOIN site ss ON ss.site_id = v_shelter
   WHERE b.batch_id = p_batch;
  SELECT p_batch, v_shelter, u.user_id, p_at, v_score, v_km
    FROM app_user u WHERE u.site_id = v_shelter AND u.role = 'SHELTER' LIMIT 1;
END$$

-- The shelter cancels its live claim at p_at.
CREATE PROCEDURE seed_cancel(p_batch INT UNSIGNED, p_at DATETIME, p_reason VARCHAR(255))
BEGIN
  IF p_at < NOW() THEN
  UPDATE claim SET status = 'CANCELLED', closed_at = p_at, close_reason = p_reason
   WHERE batch_id = p_batch AND status = 'ACTIVE';
  END IF;
END$$

-- Back-fill forecasts (no alerts) for the last 14 days before the load date
CREATE PROCEDURE seed_forecast(p_date DATE)
BEGIN
  IF p_date < CURRENT_DATE AND p_date >= CURRENT_DATE - INTERVAL 14 DAY THEN
    CALL sp_generate_forecast(p_date, FALSE);
  END IF;
END$$

-- A volunteer trip starting at p_start for the live claims of the given
-- batches. Uses the real sp_create_trip for stop order and ETAs, then
-- fills in the historical arrival times, custody events and outcome.
-- Volunteer = verified, available, can carry the load, fewest trips so
-- far (spreads the work). Food handed over (arrival + 4 min) after
-- safe_until, or the batch listed in p_fail_batch, fails the hygiene
-- check: the same rule sp_record_delivery applies to live deliveries.
CREATE PROCEDURE seed_trip(p_batches JSON, p_start DATETIME, p_fail_batch INT UNSIGNED, p_temp_drop DECIMAL(4,1))
proc: BEGIN
  DECLARE v_claims JSON; DECLARE v_load DECIMAL(9,2); DECLARE v_vol INT UNSIGNED;
  DECLARE v_trip INT UNSIGNED; DECLARE v_done BOOLEAN DEFAULT FALSE;
  DECLARE v_seq TINYINT UNSIGNED; DECLARE v_type VARCHAR(6); DECLARE v_eta DATETIME;
  DECLARE v_arr DATETIME; DECLARE v_lag INT DEFAULT 0;
  DECLARE v_failed BOOLEAN DEFAULT FALSE; DECLARE v_i INT DEFAULT 0;
  DECLARE cur CURSOR FOR SELECT stop_seq, stop_type, planned_eta FROM trip_stop
                          WHERE trip_id = v_trip ORDER BY stop_seq;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = TRUE;
  IF p_start >= NOW() THEN LEAVE proc; END IF;   -- history only

  SELECT JSON_ARRAYAGG(c.claim_id), SUM(b.quantity_kg) INTO v_claims, v_load
    FROM JSON_TABLE(p_batches, '$[*]' COLUMNS (id INT UNSIGNED PATH '$')) j
    JOIN claim c ON c.batch_id = j.id AND c.status = 'ACTIVE'
    JOIN surplus_batch b ON b.batch_id = c.batch_id AND b.safe_until > p_start;
  IF v_claims IS NULL THEN LEAVE proc; END IF;

  SELECT v.user_id INTO v_vol
    FROM volunteer v
   WHERE v.verified_at IS NOT NULL AND v.is_available AND v.max_load_kg >= v_load
   ORDER BY (SELECT COUNT(*) FROM pickup_trip t WHERE t.volunteer_id = v.user_id), v.max_load_kg, v.user_id
   LIMIT 1;
  IF v_vol IS NULL THEN LEAVE proc; END IF;

  BEGIN
    -- sp_create_trip refuses a route that would deliver food late
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET v_failed = TRUE;
    CALL sp_create_trip(v_vol, v_claims, p_start, v_trip);
  END;
  IF v_failed THEN
    -- fall back to one trip per batch (recursion depth 1)
    IF JSON_LENGTH(p_batches) > 1 THEN
      WHILE v_i < JSON_LENGTH(p_batches) DO
        CALL seed_trip(JSON_ARRAY(JSON_EXTRACT(p_batches, CONCAT('$[', v_i, ']'))), p_start, p_fail_batch, p_temp_drop);
        SET v_i = v_i + 1;
      END WHILE;
    END IF;
    LEAVE proc;     -- a single batch that cannot arrive in time is left to expire
  END IF;
  UPDATE pickup_trip SET status = 'IN_PROGRESS', started_at = p_start WHERE trip_id = v_trip;

  OPEN cur;
  stops: LOOP
    FETCH cur INTO v_seq, v_type, v_eta;
    IF v_done THEN LEAVE stops; END IF;
    SET v_lag = v_lag + FLOOR(RAND(v_trip * 31 + v_seq) * 6);       -- a few minutes of delay
    SET v_arr = v_eta + INTERVAL v_lag MINUTE;
    UPDATE trip_stop SET arrived_at = v_arr, departed_at = v_arr + INTERVAL 5 MINUTE
     WHERE trip_id = v_trip AND stop_seq = v_seq;
    IF v_type = 'PICKUP' THEN
      SELECT c.batch_id, c.claim_id, v_trip, 'PICKED_UP', v_arr + INTERVAL 5 MINUTE, v_vol,
             CASE b.storage WHEN 'HOT_HELD' THEN 68.0 WHEN 'CHILLED' THEN 4.0 ELSE 29.0 END
        FROM trip_item ti JOIN claim c ON c.claim_id = ti.claim_id JOIN surplus_batch b ON b.batch_id = c.batch_id
       WHERE ti.trip_id = v_trip AND ti.pickup_seq = v_seq;
      UPDATE surplus_batch b JOIN claim c ON c.batch_id = b.batch_id AND c.status = 'ACTIVE'
        JOIN trip_item ti ON ti.claim_id = c.claim_id
         SET b.status = 'IN_TRANSIT' WHERE ti.trip_id = v_trip AND ti.pickup_seq = v_seq;
    ELSE
      -- hygiene check at the door: on time and (for the chosen batch) temperature
      SELECT c.batch_id, c.claim_id, v_trip, 'HYGIENE_CHECK', v_arr + INTERVAL 2 MINUTE,
             (SELECT user_id FROM app_user WHERE site_id = c.shelter_site_id AND role = 'SHELTER' LIMIT 1),
             CASE WHEN b.batch_id = p_fail_batch THEN p_temp_drop
                  WHEN b.storage = 'HOT_HELD' THEN 62.0 WHEN b.storage = 'CHILLED' THEN 6.0 ELSE 30.0 END,
             (v_arr + INTERVAL 4 MINUTE <= b.safe_until AND b.batch_id <> COALESCE(p_fail_batch, 0)),
             CASE WHEN v_arr + INTERVAL 4 MINUTE > b.safe_until THEN 'arrived after safe-until time'
                  WHEN b.batch_id = p_fail_batch THEN 'hot food below 60 C on arrival' END
        FROM trip_item ti JOIN claim c ON c.claim_id = ti.claim_id JOIN surplus_batch b ON b.batch_id = c.batch_id
       WHERE ti.trip_id = v_trip AND ti.drop_seq = v_seq;
      SELECT c.batch_id, c.claim_id, v_trip, 'DELIVERED', v_arr + INTERVAL 4 MINUTE, v_vol
        FROM trip_item ti JOIN claim c ON c.claim_id = ti.claim_id JOIN surplus_batch b ON b.batch_id = c.batch_id
       WHERE ti.trip_id = v_trip AND ti.drop_seq = v_seq
         AND v_arr + INTERVAL 4 MINUTE <= b.safe_until AND b.batch_id <> COALESCE(p_fail_batch, 0);
      -- outcome is decided first into a temp table: the claim trigger
      -- updates surplus_batch, so the UPDATE itself must not read it (error 1442)
      DROP TEMPORARY TABLE IF EXISTS tmp_outcome;
      CREATE TEMPORARY TABLE tmp_outcome
      SELECT c.claim_id,
             IF(v_arr + INTERVAL 4 MINUTE <= b.safe_until AND b.batch_id <> COALESCE(p_fail_batch, 0), 'FULFILLED', 'REJECTED') AS new_status,
             IF(v_arr + INTERVAL 4 MINUTE > b.safe_until, 'arrived after safe-until time',
                IF(b.batch_id = p_fail_batch, 'failed hygiene check: temperature', NULL)) AS reason
        FROM trip_item ti JOIN claim c ON c.claim_id = ti.claim_id JOIN surplus_batch b ON b.batch_id = c.batch_id
       WHERE ti.trip_id = v_trip AND ti.drop_seq = v_seq;
      UPDATE claim c JOIN tmp_outcome o ON o.claim_id = c.claim_id
         SET c.status = o.new_status, c.closed_at = v_arr + INTERVAL 4 MINUTE, c.close_reason = o.reason;
      DROP TEMPORARY TABLE tmp_outcome;
    END IF;
  END LOOP;
  CLOSE cur;
  UPDATE pickup_trip SET status = 'COMPLETED',
         completed_at = (SELECT MAX(departed_at) FROM trip_stop WHERE trip_id = v_trip)
   WHERE trip_id = v_trip;
END$$
DELIMITER ;

